        // Creditor ID/IBAN -> PLCN_otherAccno -> MSGDB.OTHER_ACCNO
		path = '/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlTxRef/CdtrAcct/Id/IBAN';
		value = getValueFromPath(Document, path);
