		setHeader(map, "PLCN_benBankAddr1", value);
        logger.trace("extractSepaMsgDataDbToDbFlow:  CdtrAdrLine1 / PLCN_benBankAddr1 = " + value);
		
        path = '/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlTxRef/Cdtr/Pty/PstlAdr/AdrLine[2]';
