function accountValidation(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	
	logger.info("In accountValidation");

	var custom13 = getHeader(map, "PLCN_custom13");
	logger.info("accountValidation: custom13 = " + custom13);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("accountValidation: msgFamily = " + msgFamily);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("accountValidation: msgDirection = " + msgDirection);
	
	if(msgFamily == "SEPAINST" || msgFamily == "SEPA") {
		var msgType = getHeader(map, "PLCN_msgType");
		logger.info("accountValidation: msgType = " + msgType);

		var messageBody = convertDocumentToString(Document); //inMsg.getBody(java.lang.String.class);
		logger.trace("accountValidation: messageBody = " + messageBody);
		setHeader(map, "ACEDB_originalBodyAV", messageBody);
		
		var institutionId =  getHeader(map, "PLCN_institutionId");
		logger.info("accountValidation: institutionId = " + institutionId);

		var key2 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RMG" + "." + "RMG_CONF";
		logger.info("accountValidation: key2 = " + key2);

		var value2 = memTblGetTableValue(map, "INST_PARAM", key2);
		logger.info("accountValidation: value2 = " + value2);

		if(msgType == "pacs.008.001.08") {
			if(msgDirection == "I") {
				var dbtrAcct = getValueFromPath(Document, "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/DbtrAcct/Id/IBAN");
				logger.info("accountValidation: dbtrAcct = " + dbtrAcct);
				setHeader(map, "PLCN_accountID", dbtrAcct);
			}else {
			var cdtrAcct = getValueFromPath(Document, "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/CdtrAcct/Id/IBAN");
			logger.info("accountValidation: cdtrAcct = " + cdtrAcct);
			setHeader(map, "PLCN_accountID", cdtrAcct);
			}
		}else if(msgType == "pacs.004.001.09") {
			var orgnlMsgNmId = getValueFromPath(Document, '/Document/PmtRtr/OrgnlGrpInf/OrgnlMsgNmId');
			logger.info("accountValidation: orgnlMsgNmId = " + orgnlMsgNmId);  

			if(orgnlMsgNmId == "pacs.003.001.08") {
				if(msgDirection == "I") {
					var cdtrAcct = getValueFromPath(Document, '/Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN');
					logger.info("accountValidation: cdtrAcct = " + cdtrAcct);
					setHeader(map, "PLCN_accountID", cdtrAcct);
				}else {
					var dbtrAcct = getValueFromPath(Document, '/Document/PmtRtr/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN');
					logger.info("accountValidation: dbtrAcct = " + dbtrAcct);
					setHeader(map, "PLCN_accountID", dbtrAcct);
				}
			}else{
				if(msgDirection == "I") {
					var cdtrAcct = getValueFromPath(Document, '/Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN');
					logger.info("accountValidation: cdtrAcct = " + cdtrAcct);
					setHeader(map, "PLCN_accountID", cdtrAcct);
				}else {
					var dbtrAcct = getValueFromPath(Document, '/Document/PmtRtr/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN');
				 	logger.info("accountValidation: dbtrAcct = " + dbtrAcct);
				 	setHeader(map, "PLCN_accountID", dbtrAcct);
				}				
			}
		}else if(msgType == "pacs.003.001.08") {
			if(msgDirection == "I") {
				var cdtrAcct = getValueFromPath(Document, '/Document/FIToFICstmrDrctDbt/DrctDbtTxInf/CdtrAcct/Id/IBAN');
				logger.info("accountValidation: cdtrAcct = " + cdtrAcct);
				setHeader(map, "PLCN_accountID", cdtrAcct);
			}else {
				var dbtrAcct = getValueFromPath(Document, '/Document/FIToFICstmrDrctDbt/DrctDbtTxInf/DbtrAcct/Id/IBAN');
				logger.info("accountValidation: dbtrAcct = " + dbtrAcct);
				setHeader(map, "PLCN_accountID", dbtrAcct);
			}
		}else if(msgType == "pacs.007.001.09") {
			if(msgDirection == "I") {
				var cdtrAcct = getValueFromPath(Document, '/Document/FIToFIPmtRvsl/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN');
				logger.info("accountValidation: cdtrAcct = " + cdtrAcct);
				setHeader(map, "PLCN_accountID", cdtrAcct);
			}else {
				var dbtrAcct = getValueFromPath(Document, '/Document/FIToFIPmtRvsl/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN');
				logger.info("accountValidation: dbtrAcct = " + dbtrAcct);
				setHeader(map, "PLCN_accountID", dbtrAcct);
			}
		}

		if(msgType == "pacs.004.001.09") {
			var orgnlMsgNmId = getValueFromPath(Document, '/Document/PmtRtr/TxInf/OrgnlGrpInf/OrgnlMsgNmId');
			logger.info("accountValidation: orgnlMsgNmId = " + orgnlMsgNmId);
			/* if(isPatternPresent(orgnlMsgNmId, "pacs.003")){
				var sepaP4DD = true;
				setHeader(map, "PLCN_sepaP4DD", sepaP4DD);
				value2 = "";
			} */
			
			if(msgFamily == "SEPA" && msgDirection == "I") {
				value2 = "";
			}
		}
		
		if(value2) {
			var accountValidationConfigured = true;
			logger.info("accountValidation: accountValidationConfigured = " + accountValidationConfigured);
			setHeader(map, "PLCN_accountValidationConfigured", accountValidationConfigured);		
		}else {
			var accountValidationConfigured = false;
			logger.info("accountValidation: accountValidationConfigured = " + accountValidationConfigured);
			setHeader(map, "PLCN_accountValidationConfigured", accountValidationConfigured);
		}
	}else {
	var accountValidationConfigured = false;
		logger.info("accountValidation: accountValidationConfigured = " + accountValidationConfigured);
	setHeader(map, "PLCN_accountValidationConfigured", accountValidationConfigured);
	}

	logger.info("accountValidation: accountValidationConfigured = " + getHeader(map, "PLCN_accountValidationConfigured")); 

	if(accountValidationConfigured == false) {
		setHeader(map, "PLCN_accountValidationExit", false);
	}
}

