function checkRejectFlag(exchange) {
	logger.info("In checkRejectFlag rule.");

	var inMsg = exchange.getIn();
	
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var fDebulkData = exchange.getProperty("Plcn_FileDebulkData");
	logger.info("checkRejectFlag:fDebulkData = " + fDebulkData);

	var rejectFlag = fDebulkData.isRejectFileFlag();
	logger.info("checkRejectFlag:rejectFlag = " + rejectFlag);	

	if(fDebulkData && rejectFlag == true) {
		setHeader(map, "PLCN_rejectFileFlag", "true");
	}else {
		setHeader(map, "PLCN_rejectFileFlag", "false");
	}

	logger.info("checkRejectFlag done.");
}

function enrichValueDate(exchange) {
	var currDate;
	var msgDate;
	var msgType;
	var msgDatePath;
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var stringMessage = inMsg.getBody(java.lang.String.class);
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	
	logger.info("enrichValueDate: stringMessage = "+ stringMessage);
	
	currDate = getDate();
	logger.info("enrichValueDate: currDate = "+ currDate);
	
	msgType = getHeader(map, "PLCN_msgType");
	if(!msgType){
		msgType = getHeader(map, "msgClsType");
	}
	logger.info("enrichValueDate: msgType = " + msgType);
	
	if(isPatternPresent(msgType, "pacs.008")) {
		msgDate = dataBetweenTokens("<IntrBkSttlmDt>", "</IntrBkSttlmDt>", stringMessage);
		logger.info("enrichValueDate: msgDate = "+ msgDate);
	}
	
	if(isPatternPresent(msgType, "pacs.004")) {
		msgDate = dataBetweenTokens("<IntrBkSttlmDt>", "</IntrBkSttlmDt>", stringMessage);
		logger.info("enrichValueDate: msgDate = "+ msgDate);
	}

	if(isPatternPresent(msgType, "pacs.003")) {
		msgDate = dataBetweenTokens("<IntrBkSttlmDt>", "</IntrBkSttlmDt>", stringMessage);
		logger.info("enrichValueDate: msgDate = "+ msgDate);
	}
	if(isPatternPresent(msgType, "camt.056")) {
		msgDate = dataBetweenTokens("<OrgnlIntrBkSttlmDt>", "</OrgnlIntrBkSttlmDt>", stringMessage);
		logger.info("enrichValueDate: msgDate = "+ msgDate);
	}
	
	if(msgDate) {
		msgDate = replaceAllPattern(msgDate, "-", ""); //2023-10-20
	}
	logger.info("enrichValueDate: msgDate after removing hyphen = "+ msgDate);
	var DD;
	var MM;
	var YY;
	if(msgDate){
		DD = msgDate.substring(6, 8);
		MM = msgDate.substring(4, 6);
		YY = msgDate.substring(0, 4);
	}
	
	var validateDate = isValidDate(YY, MM, DD);
	logger.info("enrichValueDate: validation response = "+ validateDate);
	
	if(validateDate == false)
	{
		msgDate = currDate;
		logger.info("enrichValueDate: msgDate in false loop= "+ msgDate);
		//20231020
		var DD = msgDate.substring(6, 8);
		var MM = msgDate.substring(4, 6);
		var YY = msgDate.substring(0, 4);
		msgDate = YY + "-" + MM + "-" + DD;
		logger.info("enrichValueDate: msgDate after append = "+ msgDate);
		
		if(isPatternPresent(msgType, "pacs.008")) {
			logger.info("enrichValueDate: inside pacs008 loop ");
			msgDatePath = "/Document/FIToFICstmrCdtTrf/GrpHdr/IntrBkSttlmDt";
			setValueInPath(Document, msgDatePath, msgDate);
		}
		
		if(isPatternPresent(msgType, "pacs.004")) {
			msgDatePath = "/Document/PmtRtr/GrpHdr/IntrBkSttlmDt";
			setValueInPath(Document, msgDatePath, msgDate);
		}

		if(isPatternPresent(msgType, "pacs.003")) {
			msgDatePath = '/Document/FIToFICstmrDrctDbt/GrpHdr/IntrBkSttlmDt';
			setValueInPath(Document, msgDatePath, msgDate);
		}
		if(isPatternPresent(msgType, "camt.056")) {
			logger.info("enrichValueDate: inside camt.056 loop ");
			msgDatePath = "/Document/FIToFIPmtCxlReq/Undrlyg/TxInf/OrgnlIntrBkSttlmDt";
			setValueInPath(Document, msgDatePath, msgDate);
		}
		setCommentsForTransaction("00", "6909", map);
	}
	var messageBody = convertDocumentToString(Document);
	inMsg.setBody(messageBody);
	setHeader(map, "ACEDB_originalBody", messageBody);
	logger.info("enrichValueDate: function completed ");
}

function isValidDate(year, month, day) {
    if (year < 1000 || year > 9999) {
        return false; // Invalid year
    }
 
    if (month < 1 || month > 12) {
        return false; // Invalid month
    }
 
    const daysInMonth = new Date(year, month, 0).getDate();
    if (day < 1 || day > daysInMonth) {
        return false; // Invalid day for the given month and year
    }
 
    return true; // Valid date
}
 
 function checkNameSpace(exchange) {
	var payload;
	var bah;
	var interact;
	var msgType;
	var institutionId;
	var config;
	var key;

	logger.info("In checkNameSpace");

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var message = inMsg.getBody(java.lang.String.class);
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	logger.info("checkNameSpace: readMsgdb = " + readMsgdb);

	var body = inMsg.getBody(java.lang.String.class);
	logger.info("checkNameSpace: body = " + body);

	// var msgId =  readMsgdb.get("MSGDB_ID");
	// logger.info("checkNameSpace: msgId = " + msgId);

	var msgFamily = readMsgdb.get("MSG_FAMILY");
	logger.info("checkNameSpace: msgFamily = " + msgFamily);

	if((isPatternPresent(message, "</Saa:DataPDU>") || isPatternPresent(message, "</DataPDU>")) && msgFamily == "CBPR") {
		logger.info("checkNameSpace: Data PDU present..");
		setHeader(map, "PLCN_headerPresent", true);
		//truncateNameSpaceFromFile(exchange);		
	}else if((isPatternPresent(message, "</head:AppHdr>") || isPatternPresent(message, "</AppHdr>")) && msgFamily == "CBPR") {
		logger.info("checkNameSpace: AppHdr present..");
		//truncateNameSpaceFromFile(exchange);
		setHeader(map, "PLCN_headerPresent", true);
	}else {
		logger.info("checkNameSpace: No Headers are present in Document...");
		setHeader(map, "PLCN_headerPresent", false);
	}

	var count = 0;

	 for (var i = 0; i <3 ;i++) {
	 	if((isPatternPresent(message, "</Saa:DataPDU>") || isPatternPresent(message, "</DataPDU>")) || (isPatternPresent(message, "</head:AppHdr>") || isPatternPresent(message, "</AppHdr>")) || (isPatternPresent(message, "</pacs:Document>") || isPatternPresent(message, "</Document>")))
	 	count = count + 1;
	 }

	 if(count > 1) {
	 	setHeader(map, "PLCN_multipleHeader", true);
	 }else {
	 	setHeader(map, "PLCN_multipleHeader", false);
	 } 

	logger.info("checkNameSpace: headerPresent = " + getHeader(map, "PLCN_headerPresent"));
}

function truncateNameSpaceFromFile(exchange){
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var body = inMsg.getBody(java.lang.String.class);

	logger.info("In truncateNameSpaceFromFile Rule");

	//var ObjectBody = getHeader(map, "inputMsgAsString"); 
	//logger.info("truncateNameSpaceFromFile: ObjectBody = " + ObjectBody);

	//var body = ObjectBody.toString();

	logger.info("truncateNameSpaceFromFile: Body before truncation = " + body);

	// setHeader(map, "ACEDB_MSGBLOCK1", body);
	// logger.info("setMsgBlocksData: ACEDB_MSGBLOCK1 = " + getHeader(map, "ACEDB_MSGBLOCK1"));
	if(body) {
		body = body.replace(/xmlns:\w*=/g, 'xmlns=');
  		body = body.replace(/<(\/)?(\w+):/g, '<$1');
  	}
  	var outputBody;
  	//logger.info("truncateNameSpaceFromFile: Body after truncation = " + body);

  	 if(body.contains("<Document")){
        //var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Body"));
        outputBody= body.substring(body.indexOf("<Document"), body.indexOf("</Document") + 11);
        logger.info("truncateNameSpaceFromFile: outputBody after truncation = " + outputBody);
    }
    //setHeader(map, "ACEDB_MSGBLOCK1", outputBody);
	//logger.info("setMsgBlocksData: ACEDB_MSGBLOCK1 = " + getHeader(map, "ACEDB_MSGBLOCK1"));
	//inMsg.setBody(org.w3c.dom.Document.class);
	//logger.info("truncateNameSpaceFromFile: Body after parsing = " + outputBody);
	var parser = new XMLParser();
	//var Msgbody = inMsg.getBody(java.lang.String.class);
	parser.parseXML(outputBody);
	Document = parser.parseXML(outputBody);
  	inMsg.setBody(Document);
  	setHeader(map, "PLCN_orgMessage", Document);
  	//setHeader(map, "ACEDB_originalBody", outputBody);
  	setHeader(map, "inputMsgAsString", "");

	logger.info("truncateNameSpaceFromFile Rule completed..");
}

function checkOccurrencesOfTag(exchange, tagName) {
	logger.info("In checkOccurrencesOfTag rule.");

	var inMsg = exchange.getIn();
	
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var elements = Document.getElementsByTagName(tagName);
	logger.info("checkOccurrencesOfTag: elements = " + elements);

	var count = elements.length;
	logger.info("checkOccurrencesOfTag: count = " + count);

	logger.info("checkOccurrencesOfTag done.");
	return count;
}

