function genAuditInsert(exchange) {
    var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
    var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
    var msgdbMap = new HashMap();
    var audit = new HashMap();

	var custom13 = getHeader(map, "PLCN_custom13");
	logger.info("genAuditInsert: custom13 = " + custom13);
    //var queueId = getHeader(map, "PLCN_queueAudit");
    var queueId = readMsgdb.get("QUEUEID");
    var messageNo = readMsgdb.get("MESSAGENO"); 
    logger.info("genAuditInsert: queueId = " + queueId);
    logger.info("genAuditInsert: messageNo = " + messageNo);

    var complianceFlag = getHeader(map, "PLCN_complianceCheckConfigured");
    logger.info("genAuditInsert: complianceFlag = " + complianceFlag);

 	var accountEntryFlag = getHeader(map, "PLCN_accountValidationConfigured");
    logger.info("genAuditInsert: accountEntryFlag = " + accountEntryFlag);

    //MATCHING=D|CASH_FORECASTING=D|SCANNING=D|WAREHOUSE=D|
    //AUTHORIZATION=N|ACCOUNTING_ENTRY=N|DISPOSITION=Y|REVIEW=N|DUPLICATE=N|REPAIR=D|VALIDATE=D|

    var sddFlag = getHeader(map, "PLCN_sepaP4DD");
    logger.info("genAuditInsert: sddFlag=" + sddFlag);

    if(sddFlag == true) {
    	var messageBody = getHeader(map, "ACEDB_originalBody");
    	logger.info("genAuditInsert: messageBody=" + messageBody);

    	inMsg.setBody(messageBody);
    }

    if(!messageNo) {
        messageNo = getHeader(map, "PLCN_messageNo");
    }
    logger.info("genAuditInsert: messageNo = " + messageNo);

    //var queueId = getHeader(map, "PLCN_batchQueueId");
    
    if(!queueId) {
        queueId = getHeader(map, "PLCN_queueId");
    }
    logger.info("genAuditInsert:queueId = " + queueId);

    var institutionId = getHeader(map, "PLCN_institutionId");
    logger.info("genAuditInsert: institutionId = " + institutionId);

    audit.put("MESSAGENO", messageNo);
    if(queueId) {
        audit.put("QUEUEID", queueId);
    }
    audit.put("APPLICATION","SEPAPPAY");
    audit.put("MODULENAME","ACEQWRITE");
    audit.put("ACTION","WRITE");
	audit.put("INSTITUTIONID", institutionId);
    if(isPatternPresent(custom13, "ACCOUNTING_ENTRY=Y") && accountEntryFlag == true){
    	logger.info("genAuditInsert: made an api callout to Accounting Entry");
		//audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " made an api callout to Accounting Entry" +  "<" + queueId + ">");    	
		audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " made an api callout to Accounting Entry");   
		setHeader(map, "GENAUDIT", audit);
		setHeader(map, "PLCN_insertAudit", true);//TBSEETHTY-10930
		setHeader(map, "PLCNAPI_insertAudit", true);
    }else if(isPatternPresent(custom13, "SCANNING=Y") && complianceFlag == true){
    	logger.info("genAuditInsert: made an api callout to Sanctions");
    	audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " made an api callout to Sanctions");  
		setHeader(map, "GENAUDIT", audit);
		setHeader(map, "PLCN_insertAudit", true);//TBSEETHTY-10930
		setHeader(map, "PLCNAPI_insertAudit", true);
    }
}

function checkTranslationFlag(exchange) {
    var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	
	logger.info("In checkTranslationFlag");

	var institutionId = getHeader(map, "PLCN_institutionId");
	logger.info("checkTranslationFlag: institutionId = " + institutionId);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("checkTranslationFlag: msgFamily = " + msgFamily);

   	var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.STATUS_REPORT" + "." + "GENERATE_STATUS_REPORT_" + msgFamily;
    logger.info("checkTranslationFlag: key1 = " + key1);

    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
    logger.info("checkTranslationFlag: value1 = " + value1);
	value1 = value1.toUpperCase();

	// added for SSBTC-293
	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("checkTranslationFlag: msgType = " + msgType);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("checkTranslationFlag: msgDirection = " + msgDirection);
	
	if(value1 == "NO" && msgType == "pacs.008.001.08" && msgDirection == "I"){
		var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.STATUS_REPORT" + "." + "GENERATE_STATUS_REPORT_INVAL_IBAN_" + msgFamily;
		logger.info("checkTranslationFlag: key1 = " + key1);

		var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		logger.info("checkTranslationFlag: value1 = " + value1);
		value1 = value1.toUpperCase();
	}
	
	// end
	
	var prevQueueid = readMsgdb.get("PREVQUEUEID");
	logger.info("checkTranslationFlag: prevQueueid = " + prevQueueid);
	
	if(value1 == "NO" && msgType == "pacs.003.001.08" && msgDirection == "O"){
		var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.STATUS_REPORT" + "." + "GENERATE_STATUS_REPORT_INVAL_IBAN_" + msgFamily;
		logger.info("checkTranslationFlag: key1 = " + key1);

		var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		logger.info("checkTranslationFlag: value1 = " + value1);
		value1 = value1.toUpperCase();
	}

	var orgnlMsgNmIdC56Path = "/Document/FIToFIPmtCxlReq/Undrlyg/TxInf/OrgnlGrpInf/OrgnlMsgNmId";
    var orgnlMsgNmIdC56 = getValueFromPath(Document, orgnlMsgNmIdC56Path);
	logger.info("checkTranslationFlag: orgnlMsgNmIdC56 = " + orgnlMsgNmIdC56);
	if(orgnlMsgNmIdC56){
		orgnlMsgNmIdC56 = orgnlMsgNmIdC56.slice(0, 8);
	}
		
	if(msgType == "camt.056.001.08" && msgDirection == "O" && orgnlMsgNmIdC56 == "pacs.003") {
		var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.STATUS_REPORT" + "." + "GENERATE_STATUS_REPORT_" + msgFamily + "_CAMT056";
		logger.info("checkTranslationFlag: key1 = " + key1);

		var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		logger.info("checkTranslationFlag: value1 = " + value1);
		value1 = value1.toUpperCase();		
	}
	
    if(isPatternPresent(value1, "YES")) {
   		logger.info("checkTranslationFlag: generating status report");
   		setHeader(map, "PLCN_generateStatusReport", true);
    }else {
		logger.info("checkTranslationFlag: not generating status report");
    }
	
	//pacs004 ADDED BY SNEHA
	var key2 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RETURN" + "." + "GENERATE_RETURN_" + msgFamily;
    logger.info("checkTranslationFlag: key2 = " + key2);

    var value2 = memTblGetTableValue(map, "INST_PARAM", key2);
    logger.info("checkTranslationFlag: value2 = " + value2);
	value2 = value2.toUpperCase();

    if(isPatternPresent(value2, "YES")) {
   		logger.info("checkTranslationFlag: generating Return");
   		setHeader(map, "PLCN_generateReturn", true);
    }else {
		logger.info("checkTranslationFlag: not generating Return");
    }
}

