function setSchedulingResponseQueue(exchange){
	
	var queueId;
	
	logger.info("In setSchedulingResponseQueue");
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var msgdbMap = new HashMap();
	
	var schedulingReqFlag = getHeader(map, "PLCN_schedulingReq");
	logger.info("setSchedulingResponseQueue: schedulingReqFlag = " + schedulingReqFlag);
	
	if(schedulingReqFlag == "false") {
		queueId = "SEPATXNQ"
		logger.info("setSchedulingResponseQueue: queueId = " + queueId);
	}
	else if(schedulingReqFlag == "true"){
		queueId = "TXNHOLDQ"
		logger.info("setSchedulingResponseQueue: queueId = " + queueId);
	}
	
	setHeader(map, "PLCN_queueAudit", queueId);

}

function channelToLocationDerivation(exchange){
    var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
    var channelIdSource;
    var loc;
	
    logger.info("In channelToLocationDerivation");
    
    channelIdSource = getHeader(map, "PLCN_channelIdSource");
	logger.info("channelToLocationDerivation: channelIdSource = " + channelIdSource);
    loc = memTblGetTableValue(map, "CHNL_TO_LOC_MAP", channelIdSource);
    if(loc){
        setHeader(map, "PLCN_msgSegr", loc);
        logger.info("channelToLocationDerivation: derived location = " + loc);
        return;
    }else{
		logger.info("channelToLocationDerivation: no location derived from channel");
	}
}

function checkSepa21To23Translation(exchange) {
    var inMsg;
	var map;
	var readMsgdb;
    var msgType;
    var msgFamily;
    var srcMsgType;
    var tgtMsgType;

	logger.info("In checkSepa21To23Translation");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
    
	var msgType =  readMsgdb.get("MESSAGECLASSTYPE");
	logger.info("checkSepa21To23Translation: msgType = " + msgType);

	var msgFamily = readMsgdb.get("MSG_FAMILY");
	logger.info("checkSepa21To23Translation: msgFamily = " + msgFamily);
    
    var orgMsgType = readMsgdb.get("ORG_MESSAGECLASSTYPE");
    logger.info("checkSepa21To23Translation: orgMsgType = " + orgMsgType);
    
    if(orgMsgType == "PROP"){
        if(msgType.toLowerCase() == "pacs.008.001.08") {
            logger.info("checkSepa21To23Translation: translating to V23 pacs.008");
		srcMsgType = "SepaPacs.008.001.02";
		setHeader(map, "SRC_PaymentType",srcMsgType);    
		tgtMsgType = "SepaPacs.008.001.08";
		setHeader(map, "TGT_PaymentType", tgtMsgType);
        setHeader(map, "PLCN_sepa21To23TranslationFlag", "true");
        setHeader(map, "PLCN_orgnlMsgType", "pacs.008.001.08");
        } else if(msgType.toLowerCase() == "pacs.003.001.08"){
            logger.info("checkSepa21To23Translation: translating to V23 pacs.003");
		srcMsgType = "SepaPacs.003.001.02";
		setHeader(map, "SRC_PaymentType",srcMsgType);
		tgtMsgType = "SepaPacs.003.001.08";
		setHeader(map, "TGT_PaymentType", tgtMsgType);
        setHeader(map, "PLCN_sepa21To23TranslationFlag", "true");
        setHeader(map, "PLCN_orgnlMsgType", "pacs.003.001.08");
        }
	}
}

function parseFieldMultipleJs(exchange, requestArray){
    var prtyFldNm;
    var requestCode;
    var refDb;
    var secLevel;
    var str;
    var key;
    var doc;
    var kbMsg;
    var ptyInfo;
    var msgRef;
    var messageReference;
    var request;
    var i;
    var newNode;
    
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
    
	logger.info("In parseFieldMultipleJs");
    
    doc = getDocument();
    kbMsg = createElement(doc, "KbMsg"); // root
    appendElementtoNode(doc, kbMsg);

    messageReference = getHeader(map, "PLCN_messageNo");
    msgRef = createElementwithTextNode2(doc, "MsgRef", messageReference);
    appendElementtoNode(kbMsg, msgRef);

    i = 0;
    while(requestArray[i]){
        logger.info(requestArray[i].toString());
        ptyInfo = createElementwithTextNode2(doc, "PtyInfo", "");
        // newNode = kbMsg.item(0);
        // newNode.insertBefore(ptyInfo, nextNode);
        appendElementtoNode(kbMsg, ptyInfo);
        
        prtyFldNm = createElementwithTextNode2(doc, "PrtyFldNm", requestArray[i][0]);
        appendElementtoNode(ptyInfo, prtyFldNm);

        requestCode = createElementwithTextNode2(doc, "RequestCode", "CUSTOM");
        appendElementtoNode(ptyInfo, requestCode);

        refDb = createElementwithTextNode2(doc, "RefDB", requestArray[i][3]);
        appendElementtoNode(ptyInfo, refDb);

        secLevel = createElementwithTextNode2(doc, "SecLevel", requestArray[i][2]);
        appendElementtoNode(ptyInfo, secLevel);

        str = createElementwithTextNode2(doc, "Str", requestArray[i][1]);
        appendElementtoNode(ptyInfo, str);

        key = createElementwithTextNode2(doc, "Key", requestArray[i][4]);
        appendElementtoNode(ptyInfo, key);        
        
        i++;
    }
    
    request = convertDocumentToString(doc);
	if(isPatternPresent(request, "xml version")) {
		request = dataBetweenTokens("<KbMsg>","</KbMsg>", request);
		request = "<KbMsg>" + request + "</KbMsg>";
		logger.info("parseFieldJs: request = " + request);
	}
    
    logger.info("parseFieldMultipleJs: request = " + request);
    return request;
}

function readCustom5(exchange) {
	var inMsg;
	var map;
	var readMsgdb;
	var Document;

	logger.info("In readCustom5");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.trace("readCustom5: messageBody = " + messageBody);
	setHeader(map, "ACEDB_originalBody", messageBody);

	var custom5 =  readMsgdb.get("CUSTOM5");
	logger.info("readCustom5: custom5 = " + custom5);
	
	var msgId = dataBetweenTokens("PREV=", "|", custom5)
	logger.info("readCustom5: msgId = " + msgId);

	setHeader(map, "PLCN_msgDbIdP8", msgId);

	var pacs002MsgdbId = readMsgdb.get("MSGDB_ID");
	logger.info("readCustom5: pacs002MsgdbId = " + pacs002MsgdbId);
	setHeader(map, "PLCN_msgDbIdP2",pacs002MsgdbId)

}

