function accDerivation(exchange){
	var baseIban;
	var fld;
	var flag;
	var secLvl;
	var runEnv;
	var accounttype;
	var receipient;
	var value;
	var temp;
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var body = inMsg.getBody(java.lang.String.class);

	var accountLabel = getHeader(map, "PLCN_cdtrAcct");
	flag = "f";
	fld = "73";
	secLvl = "SECURITY=HIGH";
	runEnv = "BACKOFFSYS-RUN";
	baseIban = "IBAN " + accountLabel;
	key = ":ACCOUNTTYPE";
	parseFieldJs(exchange,fld,baseIban, secLvl, runEnv,key);
	var parseRequest = getHeader(map, "PLCN_ParseRequest");
	logger.info("accDerivation: parseRequest = " + parseRequest);
	logger.info("accDerivation: parseRequest.type = "+typeof parseRequest);
	var hdrMap = inMsg.getHeaders();
	var executeRoute = new ExecuteCamelRoute();
	executeRoute.callRouteWithHeader('direct://ParseAccMaster', parseRequest, new HashMap());
	var outHdrMap = executeRoute.getOutputHeader();
	var outmsg = executeRoute.getOutputBody(java.util.List.class);
	var body = executeRoute.getOutputBody(org.w3c.dom.Document.class);
	var messageBody = convertDocumentToString(body);
	logger.info("accDerivation: messageBody type = "+typeof messageBody);
	logger.info("accDerivation: Output messageBody = " + messageBody );
	logger.info("accDerivation: response = "+ outmsg);
	var orgBody = getHeader(map, "PLCN_originalMsgBody");
	logger.info("accDerivation: orgBody = "+ orgBody);
	inMsg.setBody(orgBody);

	if(messageBody){
		var responseBody = dataBetweenTokens("<Value>" , "</Value>" , messageBody); 
		logger.info("accDerivation: response Value = "+ responseBody);
		responseBody = "|".concat(responseBody); 
		responseBody = responseBody.concat("|"); 
		logger.info("backoffdrvaccFromIban: response Value = "+ responseBody);
	}
	
	temp = responseBody;

	value = dataBetweenTokens("|", "|", temp);
	value = value.trim();
	setHeader(map, "PLCN_sapAccountype", value);
	logger.info("accDerivation: PLCN_sapAccountype = " + value);
	accounttype = value;
	temp = removePattern(temp, "|" + value);

	//jsonRequestForSEPAIP(exchange);

    return;
}

function jsonRequestForSEPAIP(exchange) {
	logger.info("In jsonRequestForSEPAIP rule.");

	// var messageString = inMsg.getBody(java.lang.String.class);
	// logger.info("jsonRequestForSEPAIP: messageString = " + messageString);

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var currency;
 	var amountTrnCurr;
 	var amountLclCurr;
	var transactionType;
 	var contractNumber;
 	var valueDate;
 	var companyCode;
 	var internalIban;
 	var externalIban;
 	var endToEndId;
 	var Request;
 	var bankCode;

	setHeader(map, "PLCN_msgType", "pacs.008.001.08");
	setHeader(map, "PLCN_msgFamilyDB", "SEPA");
	setHeader(map, "PLCN_currency", "EUR");

	var msgDirection = getHeader(map, "PLCN_messageDirection");
	logger.info("jsonRequestForSEPAIP: msgDirection = " + msgDirection);
	if(msgDirection == "O") {
		setHeader(map, "PLCN_txnType", "D");
		setHeader(map, "PLCN_msgDirection", "O");
		transactionType = "DEBIT";
	}else {
		setHeader(map, "PLCN_txnType", "C");
		setHeader(map, "PLCN_msgDirection", "I");
		transactionType = "CREDIT";
	}
	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.info("jsonRequestForSEPAIP: messageBody = " + messageBody);

	// logger.info("jsonRequestForSEPAIP: before sepaUpdateRuleSntd function call..");
	 pacs008Enhancer(exchange);
	 sepaUpdateRuleSntd(exchange);
	// logger.info("jsonRequestForSEPAIP: after sepaUpdateRuleSntd function call..");

	var requestFields = inMsg.getHeaders().get("PLCN_requestFields");//getHeader(map, "PLCN_requestFields");
	logger.info("jsonRequestForSEPAIP: requestFields = " + requestFields);

	currency=requestFields.get("currency");
	logger.info("jsonRequestForSEPAIP: currency = " + currency);

	 amountTrnCurr=requestFields.get("amountTrnCurr");
	 if(amountTrnCurr) {
	 	amountTrnCurr = parseFloat(amountTrnCurr).toString();
	 }
	logger.info("jsonRequestForSEPAIP: amountTrnCurr = " + amountTrnCurr);

	 amountLclCurr=requestFields.get("amountLclCurr");
	 if(amountLclCurr) {
	 	amountLclCurr = parseFloat(amountLclCurr).toString();
	 }
	logger.info("jsonRequestForSEPAIP: amountLclCurr = " + amountLclCurr);

	//  transactionType=requestFields.get("transactionType");
	// logger.info("jsonRequestForSEPAIP: transactionType = " + transactionType);

	 contractNumber=requestFields.get("contractNumber");
	logger.info("jsonRequestForSEPAIP: contractNumber = " + contractNumber);

	 valueDate=requestFields.get("valueDate");
	logger.info("jsonRequestForSEPAIP: valueDate = " + valueDate);

	companyCode=requestFields.get("companyCode");
	logger.info("jsonRequestForSEPAIP: companyCode = " + companyCode);

	 internalIban=requestFields.get("internalIban");
	 if(internalIban) {
	 	internalIban = internalIban.trim();
	 }
	logger.info("jsonRequestForSEPAIP: internalIban = " + internalIban);

	externalIban=requestFields.get("externalIban");
	if(externalIban) {
		externalIban = externalIban.trim();
	}
	logger.info("jsonRequestForSEPAIP: externalIban = " + externalIban);

	endToEndId=requestFields.get("endToEndId");
	if(endToEndId) {
		endToEndId = endToEndId.trim();
	}
	logger.info("jsonRequestForSEPAIP: endToEndId = " + endToEndId);

	// var remittanceInfoPath = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/RmtInf';
	var remittanceInfo = requestFields.get("use1"); ;//getValueFromPath(Document, remittanceInfoPath); 
	if(remittanceInfo) {
		remittanceInfo = remittanceInfo.trim();
	}
	logger.info("jsonRequestForSEPAIP: remittanceInfo = " + remittanceInfo);

	var acceptanceTimePath = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/AccptncDtTm';
	var acceptanceTime = getValueFromPath(Document, acceptanceTimePath); 
	logger.info("jsonRequestForSEPAIP: acceptanceTime = " + acceptanceTime);
	
	var key;
	if(externalIban) {
		key = externalIban.substring(0,2);
		logger.info("jsonRequestForSEPAIP: key = " + key);
	}
	var bnkCodePos = memTblGetTableValue(map, "IBAN-NCH-POS", key);
	logger.info("jsonRequestForSEPAIP: bnkCodePos = " + bnkCodePos);

	if(bnkCodePos) {
	 	const values  = bnkCodePos.split('|');
	 	const firstPos = values[0];
	 	logger.info("jsonRequestForSEPAIP: firstPos = " + firstPos);
	 	const secondPos = values[1];
	 	logger.info("jsonRequestForSEPAIP: secondPos = " + secondPos);
	 	if(externalIban) {
	 		//bankCode = externalIban.slice(firstPos-1, secondPos-1);
	 		bankCode = externalIban.substr(firstPos-1, secondPos);
	 	}
 	}

 	logger.info("jsonRequestForSEPAIP: bankCode = " + bankCode);

	var NamePath = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/Dbtr/Nm';
	var Name = getValueFromPath(Document, NamePath); 
	logger.info("jsonRequestForSEPAIP: Name = " + Name);

	var transactioIdPath = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/PmtId/TxId';
	var transactionId = getValueFromPath(Document, transactioIdPath); 
	logger.info("jsonRequestForSEPAIP: transactionId = " + transactionId);

	var instrIdPath = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/PmtId/InstrId';
	var instrId = getValueFromPath(Document, instrIdPath); 
	logger.info("jsonRequestForSEPAIP: instrId = " + instrId);

	var groupMsgIdPath = 'Document/FIToFICstmrCdtTrf/GrpHdr/MsgId';
	var groupMsgId = getValueFromPath(Document, groupMsgIdPath); 
	logger.info("jsonRequestForSEPAIP: groupMsgId = " + groupMsgId);

	// var f003Data = getHeader(map, "PLCN_f003Msg");
	// logger.info("jsonRequestForSEPAIP: f003Data = " + f003Data);
		
	// var f007Data = getHeader(map, "PLCN_f007Msg");
	// logger.info("jsonRequestForSEPAIP: f007Data = " + f007Data);

	var RequestType = getHeader(map,"PLCN_sapAccountype");
	logger.info("jsonRequestForSEPAIP: RequestType = " + RequestType);

	var productType;
	if(RequestType == "PC") {
		productType = "PASSIVE";
	}else {
		productType = "CASH_CARD";
	}

		Request = {
			payment : {
				"currency":currency,
				"amount":amountTrnCurr,
				"amountLocalCurrency":amountLclCurr,
				"transactionType":transactionType,
				"valueDate":valueDate,
				"remittanceInformation":remittanceInfo,
				"acceptanceTime":acceptanceTime,
				"document":messageBody		
			},
			debtor : {
				"bankCode":bankCode,
				"IBAN":externalIban,
				"Name":	Name	
			},
			creditor : {
				"IBAN":internalIban
			},
			contract : {
				"contractNumber":contractNumber,
				"companyCode":companyCode,
			"productType":productType		
			},
			transactionIdentifiers : {
				"endToEndID":endToEndId,
				"transactionId":transactionId,
				"instructionID":instrId,
				"groupMessageId":groupMsgId
			}
		};

	setHeader(map, "PLCN_instantPaymentCall", true);

	var apiRequest = JSON.stringify(Request);
	logger.info("jsonRequestForSEPAIP: apiRequest = " + apiRequest);
	inMsg.setBody(apiRequest);
}

function getHttpResponseCode(exchange) {
	var inMsg;
	var map;
	var readMsgdb;
	var Document;

	logger.info("In getHttpResponseCode");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var camelHttpResponseCode = getHeader(map, "CamelHttpResponseCode");
	//camelHttpResponseCode = 200; //for testing
	logger.info("getHttpResponseCode: camelHttpResponseCode = " + camelHttpResponseCode);
	logger.info("getHttpResponseCode: typeof camelHttpResponseCode = " + typeof camelHttpResponseCode);
	

	if(camelHttpResponseCode.toString().substring(0, 1) == "2") {
		setHeader(map, "PLCN_successCall", true);	
	}else {
		setHeader(map, "PLCN_successCall", false);
		setCommentsForTransaction("00", "8454", map);
	}
}

function dbOperationAccountingEntry(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var audit = new HashMap();
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	var queueId;

	logger.info("In dbOperationAccountingEntry");

	var accEntrySntd = getHeader(map, "PLCN_AccountingEntrySNTD");
	logger.info("dbOperationAccountingEntry: accEntrySntd = " + accEntrySntd);

	var postAccountingEntry = getHeader(map, "PLCN_postAccountingEntry");
	logger.info("dbOperationAccountingEntry: postAccountingEntry = " + postAccountingEntry);

	var messageNo = readMsgdb.get("MESSAGENO");
	logger.info("dbOperationAccountingEntry: messageNo = " + messageNo);

	var institutionId =  readMsgdb.get("INSTITUTIONID");
	logger.info("dbOperationAccountingEntry: institutionId = " + institutionId);

	if(postAccountingEntry.toString() == "true" && accEntrySntd) {
		if(accEntrySntd.toString() == "true") {
			var camelHttpResponseCode = getHeader(map, "CamelHttpResponseCode");
			logger.info("dbOperationAccountingEntry: camelHttpResponseCode = " + camelHttpResponseCode);

			if(camelHttpResponseCode.toString().substring(0, 1) == "2") {
				setHeader(map, "PLCN_successCall", true);
				queueId = "PROCDQ";
			}else {
				setHeader(map, "PLCN_successCall", false);
				setCommentsForTransaction("00", "8454", map);
				queueId = "ERRORQ";
			}
		}
	}else {
		queueId = "PROCDQ";
	}

	var messageNo = readMsgdb.get("MESSAGENO");
	logger.info("dbOperationAccountingEntry: messageNo = " + messageNo);

	var institutionId =  readMsgdb.get("INSTITUTIONID");
	logger.info("dbOperationAccountingEntry: institutionId = " + institutionId);

	audit.put("MESSAGENO", messageNo);
	audit.put("APPLICATION","SEPAPPAY");
	audit.put("MODULENAME","ACEQWRITE");
	audit.put("ACTION","WRITE");
	audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " read from DB and written into Queue " +  "<" + queueId + ">");
	audit.put("INSTITUTIONID", institutionId);
	audit.put("QUEUEID", queueId);	

	setHeader(map, "GENAUDIT", audit);

	logger.info("dbOperation completed");
}

function checkAccountingEntryConfig(exchange) {
    var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
    var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	logger.info("In checkAccountingEntryConfig");

	var institutionId =  readMsgdb.get("INSTITUTIONID");
	logger.info("checkAccountingEntryConfig: institutionId = " + institutionId);

   	var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.ACCOUNTING_ENTRY" + "." + "CONFIG";
    logger.info("checkAccountingEntryConfig: key1 = " + key1);

    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
    logger.info("checkAccountingEntryConfig: value1 = " + value1);

    var msgType = getHeader(map, "PLCN_msgType");
	logger.info("checkAccountingEntryConfig: msgType = " + msgType);
	if(!msgType){
		var msgType =  readMsgdb.get("MESSAGECLASSTYPE");
	    logger.info("checkAccountingEntryConfig: msgType = " + msgType);
	}

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("accountValidation: msgFamily = " + msgFamily);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("accountValidation: msgDirection = " + msgDirection);

    if(value1) {
   		logger.info("checkAccountingEntryConfig: calling Accounting Entry route for " + value1);
		setHeader(map, "PLCN_AccountingEntry"+value1, true);
    }else {
   		logger.info("checkAccountingEntryConfig: calling Accounting Entry route for Product");
   		if(msgType =='pacs.008.001.08' && msgFamily == 'SEPAINST' && msgDirection == 'I') {
   			setHeader(map, "PLCN_AccountingEntryPRD", false);
   		}else {
   			setHeader(map, "PLCN_AccountingEntryPRD", true);
   		}    	
    }

    var txStsp;
	
	if(msgType == 'pacs.002.001.10') {
		txSts = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/OrgnlGrpInfAndSts/GrpSts");
		logger.info("checkAccountingEntryConfig: txSts from GrpSts = " + txSts);

		if(!txSts) {
			txSts = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts");
			logger.info("checkAccountingEntryConfig: txSts from TxSts = " + txSts);
		}
		setHeader(map, "PLCN_trxnStatus", txSts);

		if(txSts == "ACCP") {
			setHeader(map, "PLCN_postAccountingEntry"+value1, true);
		}else {
			setHeader(map, "PLCN_postAccountingEntry"+value1, false);
		}

		var orgnlEndToEndId = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlEndToEndId");
		logger.info("checkAccountingEntryConfig: orgnlEndToEndId = " + orgnlEndToEndId);
		setHeader(map, "PLCN_orgnlEndToEndId", orgnlEndToEndId);
	}
}

function checkAccountingEntryConfigPrd(exchange) {
    var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
    var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	logger.info("In checkAccountingEntryConfigPrd");

	var institutionId =  readMsgdb.get("INSTITUTIONID");
	logger.info("checkAccountingEntryConfigPrd: institutionId = " + institutionId);

   	var key2 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RMG" + "." + "RMG_CONF";
    logger.info("checkAccountingEntryConfigPrd: key2 = " + key2);

    var value2 = memTblGetTableValue(map, "INST_PARAM", key2);
    //value2 = "OPTION1"; //for testing
    logger.info("checkAccountingEntryConfigPrd: value2 = " + value2);

   	var key3 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RMG" + "." + "ACC_MIR_FLG";
    logger.info("checkAccountingEntryConfigPrd: key3 = " + key3);

    var value3 = memTblGetTableValue(map, "INST_PARAM", key3);
    logger.info("checkAccountingEntryConfigPrd: value3 = " + value3);

    var msgType = getHeader(map, "PLCN_msgType");
	logger.info("checkAccountingEntryConfig: msgType = " + msgType);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("checkAccountingEntryConfig: msgFamily = " + msgFamily);

	var txSts;

	if(msgType == 'pacs.004.001.09' && msgFamily == 'SEPAINST') {
		txSts = "ACCP";
	}else {
		txSts = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/OrgnlGrpInfAndSts/GrpSts");
    	logger.info("checkAccountingEntryConfigPrd: txSts from GrpSts = " + txSts);
	}

	if(!txSts) {
		txSts = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/TxInfAndSts/TxSts");
		logger.info("checkAccountingEntryConfigPrd: txSts from TxSts = " + txSts);
	}

	if(txSts == "ACCP") {
		if(value2 == "OPTION1") {
			setHeader(map, "PLCN_postAccountingEntryPrd", true);
		}else if((value2 == "OPTION3" || value2 == "OPTION4") && value3 == "ON") {
			setHeader(map, "PLCN_postAccountingEntryPrd", true);
		}else {
			setHeader(map, "PLCN_postAccountingEntryPrd", false);
		}
	}else {
		setHeader(map, "PLCN_postAccountingEntryPrd", false);
	}

	var orgnlEndToEndId = getValueFromPath(Document, "/Document/FIToFIPmtStsRpt/TxInfAndSts/OrgnlEndToEndId");
	logger.info("dbOperationAccountingEntry: orgnlEndToEndId = " + orgnlEndToEndId);
	setHeader(map, "PLCN_orgnlEndToEndId", orgnlEndToEndId);
}

function genAuditInsertAccEntry(exchange) {
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
    var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
    var msgdbMap = new HashMap();
    var audit = new HashMap();

    var queueId = readMsgdb.get("QUEUEID");
    var messageNo = readMsgdb.get("MESSAGENO"); 
    logger.info("genAuditInsertAccEntry: queueId = " + queueId);
    logger.info("genAuditInsertAccEntry: messageNo = " + messageNo);

    if(!messageNo) {
        messageNo = getHeader(map, "PLCN_messageNo");
    }
    logger.info("genAuditInsert: messageNo = " + messageNo);

    //var queueId = getHeader(map, "PLCN_batchQueueId");
    
    if(!queueId) {
        queueId = getHeader(map, "PLCN_queueId");
    }
    logger.info("genAuditInsertAccEntry: queueId = " + queueId);

    var institutionId = getHeader(map, "PLCN_institutionId");
    logger.info("genAuditInsertAccEntry: institutionId = " + institutionId);

    audit.put("MESSAGENO", messageNo);
    if(queueId) {
        audit.put("QUEUEID", queueId);
    }

    var orgnlEndToEndId = getHeader(map, "PLCN_orgnlEndToEndId");
    logger.info("genAuditInsertAccEntry: orgnlEndToEndId = " + orgnlEndToEndId);

    audit.put("APPLICATION","SEPAPPAY");
    audit.put("MODULENAME","ACEQWRITE");
    audit.put("ACTION","WRITE");
	audit.put("AUDITTEXT","Funds transfered successfully for original instruction with EndToEndId " + orgnlEndToEndId);
    audit.put("INSTITUTIONID", institutionId);
	logger.info("genAuditInsert: audit = " + audit);
    setHeader(map, "GENAUDIT", audit);
	logger.info("genAuditInsertAccEntry: Funds transfered successfully for original instruction with EndToEndId " + orgnlEndToEndId);
}

