function validateHMAC(exchange) {
	var validLAU;
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var i = 1;
	var swiftAGI = "";
	var lau = new AuthCodeGenerator();
	var jsHelper = new JSHelperClass();
	var tmpData;
	var startToken;
	var endToken;
	var keyID;
	var originalHash;
	
	logger.info("In validateHMAC");
	
	var readMsgBlocks = inMsg.getHeaders().get("ACEQ_READ_MSGBLOCKS");
	var msgBlock153 = readMsgBlocks.get("MSGBLOCK153");
	logger.info("validateHMAC: msgBlock153 = " + msgBlock153);
	
	var institutionId = getHeader(map, "PLCN_institutionId");
	logger.info("validateHMAC: institutionId = " + institutionId);
	
   	var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.SWIFT_AGI" + "." + "VALIDATE_HMAC_LAU";
    logger.info("validateHMAC: key1 = " + key1);

    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
    logger.info("validateHMAC: value1 = " + value1);
	
	if(msgBlock153 && value1 == "YES") {
		var count = memTblGetTableValue(map, "SWFTAGI_RECV_MAP", "COUNT")
		logger.info("validateHMAC: count = " + count);
		count = parseInt(count);
		
		while(i<=count) {
			var field = memTblGetTableValue(map, "SWFTAGI_RECV_MAP", "FIELD"+i.toString());
			logger.info("validateHMAC: field = " + field);
			startToken = "<"+field+">";
			endToken= "</"+field+">"
			tmpData = dataBetweenTokens(startToken, endToken, msgBlock153);
			logger.info("validateHMAC: tmpData = " + tmpData);
			
			if(field == "HMAC"){
				originalHash = tmpData;
				logger.info("validateHMAC: originalHash = " + originalHash);
			}else if(field == "HMACKeyId") {
				keyID = tmpData;
				logger.info("validateHMAC: keyID = " + keyID);
			}else if((field != "HMAC" || field != "HMACKeyId") && tmpData) {
				logger.info("validateHMAC: appending swiftAGI data for " + field);
				swiftAGI = swiftAGI + tmpData;
			}
			i++;
		}
		
		logger.info("validateHMAC: Complete swiftAGI = " + swiftAGI);

		var msgType = getHeader(map, "PLCN_msgType");
		logger.info("validateHMAC: msgType = " + msgType);
		var codeValue;
		
		var msgBlock1 = readMsgBlocks.get("MSGBLOCK1");
		logger.info("validateHMAC: msgBlock1 = " + msgBlock1);
		
		if(msgBlock153.contains("<usr")) {
			var usr = extractUsrHeader(exchange);
			logger.info("validateHMAC: usr = " + usr);
			
			var payload = removePattern(msgBlock153, usr);
			logger.info("validateHMAC: payload = " + payload);		
		}
		
		if(msgType != "ACK") {
			swiftAGI = swiftAGI + payload;
			logger.info("validateHMAC: swiftAGI = " + swiftAGI);
		}

		if(msgType == "ACK") {
			codeValue = dataBetweenTokens("<PrimitiveReturnCode>", "</PrimitiveReturnCode>",msgBlock153);
			logger.info("validateHMAC: codeValue = " + codeValue);
			swiftAGI = swiftAGI+codeValue;
			//swiftAGI = swiftAGI.replace(/null+$/, '');
			logger.info("validateHMAC: swiftAGI = " + swiftAGI);
		}

		var hmac = new AuthCodeGenerator();
		var jsHelper = new JSHelperClass();
		
		var key = jsHelper.getHzlMapValue(exchange.getIn().getHeaders(), "CH_KEY", keyID);
		logger.info("validateHMAC: key = " + key);
	
		var validHMAC = hmac.validateHMACSignature_AGI(swiftAGI, key, originalHash);
		logger.info("validateHMAC: valid HMAC = " + validHMAC);
		setHeader(map, "PLCN_validHMAC", validHMAC);
		
		if(!validHMAC){
			setHeader(map, "PLCN_queueAudit", "ERRORQ");
			setHeader(map, "PLCN_displayFlag", "Y");
			setHeader(map, "PLCN_processingStage", "ERR");
			//setHeader(map,"PLCN_currentAuthLevel", "ERR=4");
			setHeader(map, "PLCN_ERRORQ", true);
			setHeader(map, "PLCN_validFlag", "false");
			setHeader(map, "PLCN_validMessage", false);
			setCommentsForTransaction("00", "5847", map);
		}
	}else {
		setHeader(map, "PLCN_validHMAC", true);
	}
	
	//createHeaderAGI(exchange);
	//createHeader(exchange);
}

function checkHeaderMsgType(exchange) {
	var inMsg;
	var map;
	var Document;

	logger.info("In checkHeaderMsgType");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();

	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	var custom5 =  readMsgdb.get("CUSTOM5");
	logger.info("checkHeaderMsgType: custom5 = " + custom5);

	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("createHeaderAGI: msgType = " + msgType);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("createHeader: msgFamily = " + msgFamily);

	if(msgFamily == "SEPAINST" && (msgType == "camt.029.001.09" || msgType == "pacs.004.001.09" || msgType == "camt.056.001.08")){
		if(isPatternPresent(custom5,"OFCT") || isPatternPresent(custom5,"ICRT") || isPatternPresent(custom5,"ORIG")) {
			logger.info("checkHeaderMsgType: inside if loop - true");
			setHeader(map, "PLCN_extractUsrData", true);
		}else {
			logger.info("checkHeaderMsgType: inside if loop - false");
			setHeader(map, "PLCN_extractUsrData", false);
		}
		//setHeader(map, "PLCN_extractUsrData", true);
		logger.info("createHeader: PLCN_extractUsrData = " + getHeader(map, "PLCN_extractUsrData"));
	}
}

function readCustom5CreateHeader(exchange) {
	var inMsg;
	var map;
	var readMsgdb;
	var Document;

	logger.info("In readCustom5CreateHeader");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.trace("readCustom5CreateHeader: messageBody = " + messageBody);
	setHeader(map, "ACEDB_originalBody", messageBody);

	var custom5 =  readMsgdb.get("CUSTOM5");
	logger.info("readCustom5CreateHeader: custom5 = " + custom5);
	
	if(custom5) {	
		var msgType = getHeader(map, "PLCN_msgType");
		logger.info("createHeaderAGI: msgType = " + msgType);
		
		if(msgType == "pacs.004.001.09") {
			var msgId = dataBetweenTokens("PREV=", "|ICRT", custom5)
			logger.info("readCustom5CreateHeader: msgId for pacs.004.001.09 = " + msgId);
			setHeader(map, "PLCN_msgblkPrev", "153");
		}

		if(msgType == "camt.029.001.09") {
			var msgId = dataBetweenTokens("PREV=", "|ORIG", custom5)
			logger.info("readCustom5CreateHeader: msgId for camt.029.001.09 = " + msgId);
			setHeader(map, "PLCN_msgblkPrev", "153");
		}

		if(msgType == "camt.056.001.08") {
			var msgId;
			if(isPatternPresent(custom5, "OCRT")) {
				msgId = dataBetweenTokens("¿PREV=", "|OFCT", custom5);
				logger.info("readCustom5CreateHeader: custom5 OFCT part for camt.056.001.08 = " + msgId);
			}else {
				msgId = dataBetweenTokens("PREV=", "|OFCT", custom5);
			}
			
			logger.info("readCustom5CreateHeader: msgId for camt.056.001.08 = " + msgId);
			setHeader(map, "PLCN_msgblkPrev", "154");	
		}

		setHeader(map, "PLCN_msgDbIdPrev", msgId);
		setHeader(map, "PLCN_extractHeaderPrev", true);
	}

	//var pacs002MsgdbId = readMsgdb.get("MSGDB_ID");
	//logger.info("readCustom5CreateHeader: pacs002MsgdbId = " + pacs002MsgdbId);
	//setHeader(map, "PLCN_msgDbIdP2",pacs002MsgdbId)
}

function extractUsrData(exchange) {
	var inMsg;
	var map;
	var Document;

	logger.info("In extractUsrData");

	inMsg = exchange.getIn();
	map = inMsg.getHeaders();
	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.info("extractUsrData: messageBody = " + messageBody);

	var sender = dataBetweenTokens("<Sender>", "</Sender>", messageBody);
	logger.info("extractUsrData: sender tag = " + sender);
	sender = dataBetweenTokens("o=", ",", sender); 

	logger.info("extractUsrData: sender = " + sender);

	var receiver = dataBetweenTokens("<Receiver>", "</Receiver>", messageBody);
	logger.info("extractUsrData: receiver tag = " + receiver);
	receiver = dataBetweenTokens("o=", ",", receiver); 

	logger.info("extractUsrData: receiver = " + receiver);

	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("createHeaderAGI: msgType = " + msgType);
	
	if(msgType == "pacs.004.001.09" || msgType == "camt.029.001.09") {
		setHeader(map, "PLCN_senderUsr", receiver);
		setHeader(map, "PLCN_receiverUsr", sender);			
	}

	if(msgType == "camt.056.001.08") {
		setHeader(map, "PLCN_senderUsr", sender);
		setHeader(map, "PLCN_receiverUsr", receiver);
	}

	var orgnlMsg = getHeader(map, "ACEDB_originalBody");
	inMsg.setBody(orgnlMsg);
}

function createHeader(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	logger.info("In createHeader");
	
	var institutionId = getHeader(map, "PLCN_institutionId");
	logger.info("createHeader: institutionId = " + institutionId);
	
   	var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.SWIFT_AGI" + "." + "CREATE_HEADER_MQPROP";
    logger.info("createHeader: key1 = " + key1);

    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
    logger.info("createHeader: value1 = " + value1);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
	logger.info("createHeader: msgDirection = " + msgDirection);
	
	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("createHeader: msgFamily = " + msgFamily);
	
	if(msgDirection == "I" && value1 == "YES" && msgFamily == "SEPAINST") {
		logger.info("Calling createHeaderAGI");
		createHeaderAGI(exchange);
	}
}

function createHeaderAGI(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var hmap = new HashMap();
	var value;
	var field;
	var paramName;
	var i = 1;
	var mType;
	var senderReferencePath;
	var strHmac = "";

	logger.info("In createHeaderAGI");

	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.info("createHeaderAGI: messageBody = " + messageBody);

	var parser = new XMLParser();
	Document = parser.parseXML(messageBody);
	
	var hmac = new AuthCodeGenerator();
	var jsHelper = new JSHelperClass();
	
	var institutionId = getHeader(map, "PLCN_institutionId");
	logger.info("createHeaderAGI: institutionId = " + institutionId); //PLCNUSNY
	
	var sourceChannelId = getHeader(map, "PLCN_sourceChannelId");
	var channelIdTarget = memTblGetTableValue(map, "MQ_CHANNEL_CONF_MAP", sourceChannelId);
	logger.info("createHeaderAGI: sourceChannelId = " + sourceChannelId);
	logger.info("createHeaderAGI: channelIdTarget = " + channelIdTarget);
	var keyHmac = jsHelper.getHzlMapValue(exchange.getIn().getHeaders(), "CH_CHANNEL_KEY", channelIdTarget);
	logger.info("createHeaderAGI: keyHmac = " + keyHmac);
	var key_idHmac = jsHelper.getHzlMapValue(exchange.getIn().getHeaders(), "CH_CHANNEL_KEY_ID", channelIdTarget);
	logger.info("createHeaderAGI: key_idHmac = " + key_idHmac);
	
	if(!keyHmac) {
		var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.SWIFT_AGI" + "." + "OUTBOUND_HMAC_EXCP_FOR_NO_KEY";
		logger.info("validateHMAC: key1 = " + key1);

		var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		logger.info("validateHMAC: value1 = " + value1);

		if(value1 == "ROUTE_TO_PELICAN_ERR") {
			setHeader(map, "PLCN_queueAudit", "ERRORQ");
			setHeader(map, "PLCN_displayFlag", "Y");
			setHeader(map, "PLCN_processingStage", "ERR");
			setHeader(map,"PLCN_invalidKey", true);
			setHeader(map, "PLCN_ERRORQ", true);
			setHeader(map, "PLCN_validFlag", "false");
			setHeader(map, "PLCN_validMessage", false);
			setCommentsForTransaction("00", "10393", map);
			return;
		}
	}

	var tableName = institutionId + "_PRM"; //PLCNUSNY_PRM_MAP
	logger.info("createHeaderAGI: tableName = " + tableName); //PLCNUSNY_PRM

	var swiftAgiMap = memTblGetTableValue(map, "CONF_SWFTAGI_MAP", tableName); //"CUST1_BIC_TO_SW";//
	logger.info("createHeaderAGI: swiftAgiMap = " + swiftAgiMap); //CUST1_BIC_TO_SW

	if(!swiftAgiMap) {
		institutionId = memTblGetTableValue(map, "INST_HIERARCHY", institutionId);
		logger.info("createHeaderAGI: parent institutionId = " + institutionId);
		tableName = institutionId + "_PRM"; //PLCNGBWB
		logger.info("createHeaderAGI: tableName = " + tableName);

		var swiftAgiMap = memTblGetTableValue(map, "CONF_SWFTAGI_MAP", tableName); //"CUST1_BIC_TO_SW";//
		logger.info("createHeaderAGI: swiftAgiMap = " + swiftAgiMap); //CUST1_BIC_TO_SW

		if(!swiftAgiMap) {
			institutionId = memTblGetTableValue(map, "INST_HIERARCHY", institutionId);
			logger.info("createHeaderAGI: grand parent institutionId = " + institutionId);
			tableName = institutionId + "_PRM"; //PLCNGBWB
			logger.info("createHeaderAGI: tableName = " + tableName);

			var swiftAgiMap = memTblGetTableValue(map, "CONF_SWFTAGI_MAP", tableName); //"CUST1_BIC_TO_SW";//
			logger.info("createHeaderAGI: swiftAgiMap = " + swiftAgiMap); //CUST1_BIC_TO_SW
		}
	}
	
	if(swiftAgiMap) {
		var receiver = getHeader(map, "PLCN_receiver"); 
		logger.info("createHeaderAGI: receiver = " + receiver); //APKEFIHHXXX

		receiver8 = receiver.substring(0, 8);
		logger.info("createHeaderAGI: receiver8 = " + receiver8); //APKEFIHHXXX

		swiftAgiMap = swiftAgiMap + "_MAP";
		
		var paramvalue = memTblGetTableValue(map, swiftAgiMap, receiver); //"SWIFT_INTERACT_PROFILE_01"
		logger.trace("createHeaderAGI: paramvalue = " + paramvalue); //SWIFT_INTERACT_PROFILE_01

		if(!paramvalue)	{
			logger.info("createHeaderAGI: receiver = DEFAULT_SEPAINST");
			paramvalue = memTblGetTableValue(map, swiftAgiMap, "DEFAULT_SEPAINST");
			logger.info("createHeaderAGI: paramvalue = " + paramvalue);
		}
	}

	if(paramvalue) {
		var key = institutionId + "."+ "SWIFT_AGI_PROFILE_NAME" + "."+ paramvalue;
		logger.info("createHeaderAGI: key = " + key); //PLCNUSNY.SWIFT_AGI_PROFILE_NAME.SWIFT_INTERACT_PROFILE_01

		var firstPath = memTblGetTableValue(map, "INST_PARAM", key); //"OPERATIONAL_CONF.BANK_PROFILE_01";//NIBCNLNV.SWIFT_AGI_PROFILE_NAME.SWIFT_INTERACT_PROFILE_01
		logger.info("createHeaderAGI: firstPath = " + firstPath); //OPERATIONAL_CONF.BANK_PROFILE_01		
	}
	
	if(firstPath) {
		var path = firstPath + ".SWIFT_AGI";
		logger.info("createHeaderAGI: path = " + path); //OPERATIONAL_CONF.BANK_PROFILE_01.SWIFT_AGI

		var profile = firstPath;
		var iPath = "";
		msgType = getHeader(map, "PLCN_msgType");
		logger.info("createHeaderAGI: msgType = " + msgType); //OPERATIONAL_CONF.BANK_PROFILE_01
		
		if(msgType == "pacs.008.001.08") {
			mType = "SEPAINSTpacs.008"; //PLCNGBWB.OPERATIONAL_CONF.BANK_PROFILE_01.INTERACT.T2pacs.008.MESSAGE_IDENTIFIER
			senderReferencePath = "/Document/FIToFICstmrCdtTrf/GrpHdr/MsgId";
			//iPath = "PACS008.MESSAGEDEFINITIONIDENTIFIER";
		}else if(msgType == "camt.056.001.08") {
		 	mType = "SEPAINSTcamt.056";
		 	senderReferencePath = "/Document/FIToFIPmtCxlReq/Assgnmt/Id";
			var undrlygCstmrCdtTrfPath = "/Document/FICdtTrf/CdtTrfTxInf/UndrlygCstmrCdtTrf"
			var undrlygCstmrCdtTrf = getValueFromPath(Document, undrlygCstmrCdtTrfPath);
			/* if(undrlygCstmrCdtTrf) {
				iPath = "PACS009COVER.MESSAGEDEFINITIONIDENTIFIER";
			}else{
				iPath = "PACS009CORE.MESSAGEDEFINITIONIDENTIFIER";
			} */
		}else if(msgType == "pacs.002.001.10") {
			mType = "SEPAINSTpacs.002";
			senderReferencePath = "/Document/FIToFIPmtStsRpt/GrpHdr/MsgId";
		}else if(msgType == "pacs.004.001.09") {
			mType = "SEPAINSTpacs.004";
			senderReferencePath = "/Document/PmtRtr/GrpHdr/MsgId";
			//iPath = "PACS004.MESSAGEDEFINITIONIDENTIFIER";
		}else if(msgType == "camt.029.001.09") {
			mType = "SEPAINSTcamt.029";
			senderReferencePath = "/Document/RsltnOfInvstgtn/Assgnmt/Id";
			//iPath = "CAMT057.MESSAGEDEFINITIONIDENTIFIER";
		}
		
		var senderReference = getValueFromPath(Document, senderReferencePath);
		logger.info("createHeaderAGI: senderReference = " + senderReference);
		
		var count = memTblGetTableValue(map, "SWFTAGI_SEND_MAP", "COUNT")
		logger.info("createHeaderAGI: count = " + count);
		count = parseInt(count);
		
		var usrDoc = getDocument();
		//logger.trace("createResponse: responseDoc = " + responseDoc);
		
		var usr = createElement(usrDoc, "usr");
		appendElementtoNode(usrDoc, usr);
		
		while(i<=count) {
			field = memTblGetTableValue(map, "SWFTAGI_SEND_MAP", "FIELD"+i.toString());
			logger.info("createHeaderAGI: field = " + field);
			
			paramName = memTblGetTableValue(map, "SWFTAGI_DATA_MAP", field);
			logger.info("createHeaderAGI: paramName = " + paramName);
			
			if(field == "HMAC"){
				if(keyHmac) {
					value = " ";
				}
				logger.info("createHeaderAGI: value = " + value);
			}else if(field == "HMACKeyId") {
				value = key_idHmac;
				logger.info("createHeaderAGI: value = " + value);
			}else {
				if(field == "Sender" || field == "Receiver") { //cn=[sender_name],ou=[sender_payment],o=[sender_bank],o=swift
					var name = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + paramName+"_NAME");
					logger.info("createHeaderAGI: value = " + value);
					if(name) {
						value = name+",";
					}
					
					var payment = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + paramName+"_PAYMENT");
					logger.info("createHeaderAGI: payment = " + payment);
					if(payment) {
						value = value+payment+",";
					}
					
					var bank = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + paramName+"_BANK");
					logger.info("createHeaderAGI: bank = " + bank);

					var bic = getHeader(map, "PLCN_"+paramName.toLowerCase()+"Usr"); //PLCN_senderUsr
					logger.info("createHeaderAGI: bic from Usr = " + bic);

					if(!bic){
						var bic = getHeader(map, "PLCN_"+paramName.toLowerCase());
						logger.info("createHeaderAGI: bic from message = " + bic);
						
						if(bic) {
							bic = bic.substring(0, 8);
							logger.info("createHeaderAGI: bic = " + bic); //APKEFIHHXXX
							bic = bic.toLowerCase();
						}
					}

					if(!bic){
						bankValue = bank;
						logger.info("createHeaderAGI: bankValue for no bic = " + bankValue);
					}else{
						bankValue = "o="+bic;
						logger.info("createHeaderAGI: bankValue for bic = " + bankValue);
					}
					
					if(field == "Receiver" && msgType == "pacs.008.001.08"){
						bankValue = bank;
						logger.info("createHeaderAGI: bankValue for pacs.008.001.08 Receiver = " + bankValue);
					}

					//var plhdr = "["+paramName.toLowerCase()+"_bic8]";
					//logger.info("createHeaderAGI: plhdr = " + plhdr);
					//var bankValue = replacePattern(bank, plhdr, bic);
					logger.info("createHeaderAGI: bankValue = " + bankValue);
					if(bankValue) {
						value = value+bankValue+",";
					}
					
					var network = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + paramName+"_NETWORK");
					logger.info("createHeaderAGI: network = " + network);					
					
					if(value) {
						value = value+network;
					}
				}else if (field == "MsgType") {
					value = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + mType + "." + "MESSAGE_IDENTIFIER");
					logger.info("createHeaderAGI: value for MsgType = " + value);
				}else if(field == "MsgRef") {
					value = senderReference;
					logger.info("createHeaderAGI: value for MsgRef = " + value);
				}else if(field == "PossibleDuplicate") {
					var possibleDuplicateFlag = getHeader(map, "PLCN_possibleDuplicate");
					logger.info("createHeaderAGI: possibleDuplicateFlag = " + possibleDuplicateFlag);
					
					if(possibleDuplicateFlag) {
						value = "Y";
						logger.info("createHeaderAGI: value for PossibleDuplicate = " + value);
					}
				}else{
					value = memTblGetTableValue(map, "INST_PARAM", institutionId + "." + path + "." + paramName);
					logger.info("createHeaderAGI: value = " + value);
				}
				
				if(field != "HMAC" || field != "HMACKeyId") {
					strHmac = strHmac + value;
					logger.info("createHeaderAGI: strHmac = " + strHmac);
				}
			}
			
			if((field == "HMAC" || field == "HMACKeyId") && value1 == "WRITE_BLANK_HMAC") {
				var fld = usrDoc.createElement(field);
				appendElementtoNode(usr, fld);				
			}
			
			if(value) {
				var fld = createElementwithTextNode(usrDoc, usr, field, value);
				appendElementtoNode(usr, fld);
			}
			i++;
		}
		
		var messageBody = inMsg.getBody(java.lang.String.class);
		logger.trace("createHeaderAGI: messageBody = " + messageBody);
		strHmac = strHmac + messageBody;
		logger.trace("createHeaderAGI: Final strHmac = " + strHmac);
		
		if(keyHmac) {
			var hmacValue = hmac.generateHMACSHA256_AGI(strHmac, keyHmac);
			logger.info("createHeaderAGI: hmacValue = " + hmacValue);

			setValueInTxtNode(usrDoc, "/usr/HMAC", hmacValue);			
		}
		
		var usrDocString = getPrettyPrint(usrDoc);
		logger.info("createHeaderAGI: usrDocString = " + usrDocString);
		usrDocString = usrDocString.trim();
		logger.info("createHeaderAGI: usrDocString after trim = " + usrDocString);

		messageBody = usrDocString + messageBody;
		logger.trace("createHeaderAGI: messageBody with header = " + messageBody);
		setHeader(map, "ACEDB_MSGBLOCK154", messageBody);
	}
}

/*
**
* This function extracts payload.
* @param {CamelExchange} exchange - The exchange.
*/
function extractPayload(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var receivedMsg = exchange.getIn().getBody(java.lang.String.class);

	logger.info("extractPayload: receivedMsg = " + receivedMsg);

	if (receivedMsg.contains("<Document")) {
		//var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Body"));
		var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Document") + 11);
		logger.info("extractPayload: payload = " + payload);
	}

	return payload;
}

function extractUsrHeader(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var receivedMsg = exchange.getIn().getBody(java.lang.String.class);

	logger.info("extractUsrHeader: receivedMsg = " + receivedMsg);

	if(receivedMsg.contains("<usr")) {
		//var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Body"));
		var payload = receivedMsg.substring(receivedMsg.indexOf("<usr"), receivedMsg.indexOf("</usr") + 6);
		logger.info("extractUsrHeader: usr = " + payload);
	}else{
		var readMsgBlocks = inMsg.getHeaders().get("ACEQ_READ_MSGBLOCKS");
		var msgBlock153 = readMsgBlocks.get("MSGBLOCK153");
		logger.info("extractUsrHeader: msgBlock153 = " + msgBlock153);
		if(msgBlock153.contains("<usr")) {
			//var payload = msgBlock153.substring(msgBlock153.indexOf("<Document"), msgBlock153.indexOf("</Body"));
			var payload = msgBlock153.substring(msgBlock153.indexOf("<usr"), msgBlock153.indexOf("</usr") + 6);
			logger.info("extractUsrHeader: usr = " + payload);
		}
	}

	return payload;
}

function processAccValidationResponse(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var reasonCode;

	logger.info("In processAccValidationResponse");

	var jsonData = exchange.getIn().getBody(java.lang.String.class); //'{ "account_ID": "12389054", "status": "SUCESS", "account_status": "Y"}' //
	logger.info("processAccValidationResponse: jsonData = " + jsonData);

	var mydata = JSON.parse(jsonData);
	logger.info("processAccValidationResponse: mydata = " + mydata);

	var accountID = mydata["account_ID"];
	logger.info("processAccValidationResponse: accountID = " + accountID);

	var status = mydata["status"];
	logger.info("processAccValidationResponse: status = " + status);

	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("processAccValidationResponse: msgType = " + msgType);

	var msgDirection = getHeader(map, "PLCN_msgDirection");
	logger.info("processAccValidationResponse: msgDirection = " + msgDirection);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("processAccValidationResponse: msgFamily = " + msgFamily);

	if(status == "SUCCESS") {
		var accountStatus = mydata["account_status"];
		logger.info("processAccValidationResponse: accountStatus = " + accountStatus);

		if(accountStatus != "Y") {
			if(msgType == "pacs.008.001.08" && msgFamily == "SEPA" && msgDirection == "O") {
				setHeader(map, "PLCN_queueAudit", "PROCDQ");
				setHeader(map, "PLCN_processingStage", "FINL");
				logger.info("processAccValidationResponse: Queue = PROCDQ");
			}else {
				setHeader(map, "PLCN_queueAudit", "ERRORQ");
				setHeader(map, "PLCN_processingStage", "ERR");
				setHeader(map, "PLCN_ERRORQ", true);
				logger.info("processAccValidationResponse: Queue = ERRORQ");				
			}
			setHeader(map, "PLCN_displayFlag", "Y");
			setHeader(map, "PLCN_validFlag", "false");
			setHeader(map, "PLCN_validMessage", false);
			setHeader(map, "PLCN_accountValidationExit", true);
			setHeader(map, "PLCN_debtorValidationExit", true);
			setCommentsForTransaction("00", "11593", map);
			if(accountStatus == "N") {
				reasonCode = "AC06";
			}else if(accountStatus == "L") {
				reasonCode = "AC04";
			}else if(accountStatus == "I") {
				reasonCode = "MS02";
			} 
			logger.info("processAccValidationResponse: reasonCode = " + reasonCode);
			setHeader(map, "PLCN_reasonCodeP2", reasonCode);
			setHeader(map, "PLCN_reasonCodeP8", reasonCode);
		}else {
			logger.info("processAccValidationResponse: valid account");
			setHeader(map, "PLCN_accountValidationExit", false);
			setHeader(map, "PLCN_debtorValidationExit", false);
		}
	}else {
		if(msgType == "pacs.008.001.08" && msgFamily == "SEPA" && msgDirection == "O") {
			setHeader(map, "PLCN_queueAudit", "PROCDQ");
			setHeader(map, "PLCN_processingStage", "FINL");
			logger.info("processAccValidationResponse: Queue = PROCDQ");
		}else {
			setHeader(map, "PLCN_queueAudit", "ERRORQ");
			setHeader(map, "PLCN_processingStage", "ERR");
			setHeader(map, "PLCN_ERRORQ", true);
			logger.info("processAccValidationResponse: Queue = ERRORQ");				
		}
		setHeader(map, "PLCN_displayFlag", "Y");
		setHeader(map, "PLCN_validFlag", "false");
		setHeader(map, "PLCN_validMessage", false);
		setHeader(map, "PLCN_accountValidationExit", true);
		setCommentsForTransaction("00", "11593", map);
		logger.info("processAccValidationResponse: invalid account");
	}


	var messageBody = getHeader(map, "ACEDB_originalBodyAV");
	inMsg.setBody(messageBody);
}

