function setUnreserveFundHeader(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();

	logger.info("In setUnreserveFundHeader");

	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);

	var messageBody = convertDocumentToString(Document);
	logger.info("setUnreserveFundHeader: messageBody = " + messageBody);
	//setHeader(map, "ACEDB_pacs008Body",messageBody);

	var ackBody = getHeader(map, "ACEDB_originalBody");
	logger.info("setUnreserveFundHeader: ackBody =" + ackBody);

	var msgType = dataBetweenTokens("<MsgType>","</MsgType>",ackBody);
	logger.info("setUnreserveFundHeader: msgType = " + msgType);
	setHeader(map, "PLCN_messageType", msgType);

	var institutionId =  getHeader(map, "PLCN_institutionId");
	logger.info("setUnreserveFundHeader: institutionId = " + institutionId);

   	var key2 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RMG" + "." + "RMG_CONF";
    logger.info("setUnreserveFundHeader: key2 = " + key2);

    var value2 = memTblGetTableValue(map, "INST_PARAM", key2);
    logger.info("setUnreserveFundHeader: value2 = " + value2);

   	var key3 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.RMG" + "." + "ACC_MIR_FLG";
    logger.info("setUnreserveFundHeader: key3 = " + key3);

    var value3 = memTblGetTableValue(map, "INST_PARAM", key3);
    logger.info("setUnreserveFundHeader: value3 = " + value3);

	var creditorAccountPath;
	var creditorAccount;
	if(msgType == "pacs.008.001.08"){
		creditorAccountPath  = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/CdtrAcct/Id/IBAN';
		creditorAccount  = getValueFromPath(Document, creditorAccountPath);
		logger.info("setUnreserveFundHeader: creditorAccount Pacs008= " + creditorAccount);
	}else if(msgType == "pacs.004.001.09") {
		creditorAccountPath  = 'Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN';
		creditorAccount  = getValueFromPath(Document, creditorAccountPath);
		logger.info("setUnreserveFundHeader: creditorAccount Pacs004= " + creditorAccount);
	}	
	setHeader(map, "PLCN_AccountId",creditorAccount);

	// var messageBody = inMsg.getBody(java.lang.String.class);
	// logger.info("setUnreserveFundHeader: Body =" + messageBody);

	if(msgType == "pacs.008.001.08" || msgType == "pacs.004.001.09") {
		if(value2 == "OPTION1") {
			setHeader(map, "PLCN_unreserveFund", true);
		}else if((value2 == "OPTION3" || value2 == "OPTION4") && value3 == "ON") {
			setHeader(map, "PLCN_unreserveFund", true);
		}else{
			setHeader(map, "PLCN_unreserveFund", false);
		}
	}else {
		setHeader(map, "PLCN_unreserveFund", false);
	}

	logger.info("setUnreserveFundHeader completed...");
}

function extractDocument(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var receivedMsg = exchange.getIn().getBody(java.lang.String.class);

	logger.info("extractDocument: receivedMsg = " + receivedMsg);

	var msgType = dataBetweenTokens("<MsgType>","</MsgType>", receivedMsg)
	logger.info("extractDocument: msgType = " + msgType);
	setHeader(map, "PLCN_orgMsgClassType",msgType);

	if(msgType == "pacs.008.001.08" || msgType == "pacs.004.001.09") {
		if (receivedMsg.contains("<Document")) {
			//var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Body"));
			var payload = receivedMsg.substring(receivedMsg.indexOf("<Document"), receivedMsg.indexOf("</Document") + 11);
			logger.info("extractDocument: payload = " + payload);
			inMsg.setBody(payload);
		}
	}
	//inMsg.setBody(payload);
}

