function createHeaderFirco(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var hmap = new HashMap();
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	var SndgInstPath;
	var RcvgInstPath;
	var FileRefPath;
	
	logger.info("In createHeaderFirco");
	
	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("createHeaderFirco: msgType = " + msgType);
	
	var messageNo = getHeader(map, "PLCN_messageNo");
	logger.info("createHeaderFirco: messageNo = " + messageNo);
	
	var msgFamily = getHeader(map, "PLCN_msgFamilyDB");
	logger.info("createHeaderFirco: msgFamily = " + msgFamily);

	var Firco1Doc = getDocument();
	
	var namespaceURI = "urn:swift:saa:xsd:saa.2.0";
	//var DataPDU = createElement(Firco1Doc, "DataPDU");
	var DataPDU = Firco1Doc.createElementNS(namespaceURI, "DataPDU");
	appendElementtoNode(Firco1Doc, DataPDU);
	
	var RevisionValue = "2.0.11";
	var Revision = createElementwithTextNode(Firco1Doc, DataPDU, "Revision", RevisionValue);
	appendElementtoNode(DataPDU, Revision);
	
	var FircoHeader = createElement(Firco1Doc, "Header");
	appendElementtoNode(DataPDU, FircoHeader);
	
	var FircoMessage = createElement(Firco1Doc, "Message");
	appendElementtoNode(FircoHeader, FircoMessage);
	
	var SenderReferenceValue = messageNo;
	var SenderReference = createElementwithTextNode(Firco1Doc, FircoMessage, "SenderReference", SenderReferenceValue);
	appendElementtoNode(FircoMessage, SenderReference);
	
	var MessageIdentifierValue = msgType;
	var MessageIdentifier = createElementwithTextNode(Firco1Doc, FircoMessage, "MessageIdentifier", MessageIdentifierValue);
	appendElementtoNode(FircoMessage, MessageIdentifier);

	var FormatValue = "File";
	var Format = createElementwithTextNode(Firco1Doc, FircoMessage, "Format", FormatValue);
	appendElementtoNode(FircoMessage, Format);
	
	var SubFormatValue = "Input";
	var SubFormat = createElementwithTextNode(Firco1Doc, FircoMessage, "SubFormat", SubFormatValue);
	appendElementtoNode(FircoMessage, SubFormat);

	var FircoSender = createElement(Firco1Doc, "Sender");
	appendElementtoNode(FircoMessage, FircoSender);
	
	var FircoSenderFullName = createElement(Firco1Doc, "FullName");
	appendElementtoNode(FircoSender, FircoSenderFullName);
	
	if(msgType == "pacs.008.001.08"){
		SndgInstPath = "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/DbtrAgt/FinInstnId/BICFI";
	}else if(msgType == "pacs.004.001.09"){
		SndgInstPath = "/Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAgt/FinInstnId/BICFI";
	}
	
	var SndgInstValue = getValueFromPath(Document, SndgInstPath);
	logger.info("createHeaderFirco: SndgInstValue = " + SndgInstValue);
	
	//var SenderX1Value = "o=sender8,o=swift";
	var SenderX1 = createElementwithTextNode(Firco1Doc, FircoSenderFullName, "X1", SndgInstValue);
	appendElementtoNode(FircoSenderFullName, SenderX1);
	
	var FircoReceiver = createElement(Firco1Doc, "Receiver");
	appendElementtoNode(FircoMessage, FircoReceiver);
	
	var FircoReceiverFullName = createElement(Firco1Doc, "FullName");
	appendElementtoNode(FircoReceiver, FircoReceiverFullName);
	
	if(msgType == "pacs.008.001.08"){
		RcvgInstPath = "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/CdtrAgt/FinInstnId/BICFI";
	}else if(msgType == "pacs.004.001.09"){
		RcvgInstPath = "/Document/PmtRtr/TxInf/OrgnlTxRef/DbtrAgt/FinInstnId/BICFI";
	}
	
	var RcvgInstValue = getValueFromPath(Document, RcvgInstPath);
	logger.info("createHeaderFirco: RcvgInstValue = " + RcvgInstValue);
	
	//var ReceiverX1Value = "o=receiver8,o=swift";
	var ReceiverX1 = createElementwithTextNode(Firco1Doc, FircoReceiverFullName, "X1", RcvgInstValue);
	appendElementtoNode(FircoReceiverFullName, ReceiverX1);
	
	var messageBody = inMsg.getBody(java.lang.String.class);
	logger.info("createHeaderFirco: messageBody = " + messageBody);
	logger.info("createHeaderFirco: typeof messageBody = " + typeof messageBody);

	var Firco1DocString = getPrettyPrint(Firco1Doc);
	logger.info("createHeaderFirco: Firco1DocString = " + Firco1DocString);
	logger.info("createHeaderFirco: TYPEOF Firco1DocString = " + typeof Firco1DocString);
	
	var messagewithTag = "<Body>".concat(messageBody);
	messagewithTag = messagewithTag.concat("</Body></DataPDU>");
	logger.info("createHeaderFirco: messagewithTag = " + messagewithTag);
	
	message = replacePattern(Firco1DocString, "</DataPDU>", messagewithTag);
	logger.info("createHeaderFirco: message = " + message);
	
	message = '<?xml version="1.0" encoding="utf-8"?>'.concat(message);
	
	if(msgFamily == 'SEPA') {
		setHeader(map, "ACEDB_MSGBLOCK154", message);
		setHeader(map, "ACEDB_MSGBLOCK189", message);
	}else if(msgFamily == 'SEPAINST') {
		setHeader(map, "ACEDB_MSGBLOCK154", messageBody);
		setHeader(map, "ACEDB_MSGBLOCK189", messageBody);
	}
	
	/* var custom13 = readMsgdb.get("CUSTOM13");
	
	if(!custom13){
		custom13 = getHeader(map, "PLCN_custom13");
	}

	logger.info("createHeaderFirco: custom13 = " + custom13);
	
	var msgDirection = readMsgdb.get("MESSAGEDIRECTION");
	logger.info("createHeaderFirco: msgDirection = " + msgDirection);
	
	var msgFamily =  readMsgdb.get("MSG_FAMILY");
	logger.info("createHeaderFirco: msgFamily = " + msgFamily);
	
	var mode = readMsgdb.get("MSG_MODE_IN");
	logger.info("createHeaderFirco: mode = " + mode);
	
	if(custom13){
		if(isPatternPresent(custom13, "SCANNING=Y")){
			if((msgType == "pacs.008.001.08" || msgType == "pacs.004.001.09") && msgDirection == "I" && mode == "MQ" && msgFamily == "SEPA") {
				custom13 = replacePattern(custom13, "SCANNING=Y|", "SCANNING=D|");
			}
		}
		logger.info("createHeaderFirco: custom13 = " + custom13);
		setHeader(map, "PLCN_custom13", custom13);
	} */
	
}

function responceMatchingFirco (exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var hmap = new HashMap();
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	var msgdbMap = new HashMap();
	
	var sourceQueueId = readMsgdb.get("QUEUEID");
	logger.info("responceMatchingFirco: sourceQueueId = " + sourceQueueId);
	
	var RefPath = "/DEHResponse/Reference";
	var RefValue = getValueFromPath(Document, RefPath);
	logger.info("responceMatchingFirco: RefValue = " + RefValue);
	
	var ResultPath = "/DEHResponse/Result";
	var ResultValue = getValueFromPath(Document, ResultPath);
	logger.info("responceMatchingFirco: ResultValue = " + ResultValue);
	
	var messageNo = readMsgdb.get("MESSAGENO");
	logger.info("responceMatchingFirco: messageNo = " + messageNo);
	
	var institutionId = readMsgdb.get("INSTITUTIONID");
	logger.info("responceMatchingFirco: institutionId = " + institutionId);
	
	var custom44 = getHeader(map, "PLCN_CUSTOM44");
	logger.info("responceMatchingFirco: PLCN_CUSTOM44 = " + custom44);
	if(!custom44){
		var encryptDecrypt = new EncryptDecrypt();
		var custom44 = encryptDecrypt.getMessageDigest("SHA-1", exchange.getIn().getBody(java.lang.String.class));
		//logger.info("updateSepaQueueId: hashCode = " + hashCode);
	}
	logger.info("responceMatchingFirco: custom44 = " + custom44);
	msgdbMap.put("CUSTOM44", custom44);
	
	var duplicateMessageFlag = getHeader(map, "PLCN_duplicateMessage");
	logger.info("responceMatchingFirco: duplicateMessageFlag = " + duplicateMessageFlag);
	
	msgdbMap.put("DISPLAY_FLAG", "Y");
	msgdbMap.put("TRANSACTIONGROUP", "PROPF");
	msgdbMap.put("TRANSREFNO", RefValue);

	var orgMsgClassType = getHeader(map, "PLCN_orgMessageClassType");
	logger.info("responceMatchingFirco: orgMsgClassType = " + orgMsgClassType);
	
	channelToLocationDerivation(exchange);
	var msgSegr = getHeader(map, "PLCN_msgSegr");
	logger.info("responceMatchingFirco: msgSegr = " + msgSegr);
	
	if(msgSegr) {
		msgdbMap.put("MSGSEGR", msgSegr);
	}
	
	msgdbMap.put("PRIORITYAMOUNT", "0.0");
	msgdbMap.put("PRIORITYAMOUNTNUM", "0.0");

	if(duplicateMessageFlag == "true"){
		msgdbMap.put("PROCESSING_STAGE", "DUPL");
		var authLevelKey = institutionId + "."+ "INSTITUTION_DETAILS.AUTHENTICATION_LEVEL.STAGES.DUPLICATE" + "." + "STAGE_ACCESS_CONTROL";
    	logger.info("responceMatchingFirco: authLevelKey = " + authLevelKey);
		var authLevelValue = memTblGetTableValue(map, "INST_PARAM", authLevelKey);
		logger.info("responceMatchingFirco: authLevelValue = " + authLevelValue);
		authLevelValue = textToNum(authLevelValue);
		var currentAuthLevel = "DUPL=" + authLevelValue;
		logger.info("responceMatchingFirco: currentAuthLevel = " + currentAuthLevel);
		msgdbMap.put("CURRENT_AUTH_LEVEL", currentAuthLevel);
		var custom5Value = getHeader(map, "PLCN_custom5Dupl");
		logger.info("responceMatchingFirco: custom5Value = " + custom5Value);
		msgdbMap.put("CUSTOM5", custom5Value);
		var queueid = "TXNDUPLQ";
	}else{
		msgdbMap.put("CUSTOM12", ResultValue);
		msgdbMap.put("CUSTOM7", "|" + RefValue + "||||||"+orgMsgClassType);	
		msgdbMap.put("PROCESS_ID", "TO-MATCH");
		//msgdbMap.put("MESSAGECLASSTYPE", "PROP");
		//msgdbMap.put("MSG_FAMILY", "XML");
		var queueid = "TMPTXVWQ";
	}
	var audit = new HashMap();

	audit.put("MESSAGENO", messageNo);
	//audit.put("SEQUENCENO", 123)
	audit.put("QUEUEID", queueid);
	audit.put("APPLICATION","SEPAPPAY");
	audit.put("MODULENAME","ACEQWRITE");
	audit.put("ACTION","WRITE");
	audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " read from DB and written into Queue " +  "<" + queueid + ">");
	audit.put("INSTITUTIONID", institutionId);
	//setHeader(map, "GENAUDIT", audit);
	logger.info("responceMatchingFirco: audit = " + audit);
	setHeader(map, "ACEQ_WRITE_MSGDB", msgdbMap);
	setHeader(map, "ACEQ_DB_OPERATION", "UPDATE");
	setHeader(map, "GENAUDIT", audit);
	logger.info("responceMatchingFirco completed");
}

