function IBSCheck(exchange) {
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var IBSCheckConfigured;
	var messageP8;
	
	logger.info("In IBSCheck");

	var custom13 = getHeader(map, "PLCN_custom13");
	logger.info("IBSCheck: custom13 = " + custom13);
	
	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("IBSCheck: msgFamily = " + msgFamily);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("IBSCheck: msgDirection = " + msgDirection);
	
	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("IBSCheck: msgType = " + msgType);

	var sepaP4DD = getHeader(map, "PLCN_sepaP4DD");
	logger.info("IBSCheck: sepaP4DD = " + sepaP4DD);
	
	if(sepaP4DD == true) {
		custom13 = replacePattern(custom13, "IBS=Y", "IBS=N");
		logger.info("IBSCheck: custom13 = " + custom13);
	}
	
	var commentsP8 = null;
	
	if(!sepaP4DD && msgType == "pacs.004.001.09" && msgDirection == "I" && msgFamily == "SEPA") {
		/* if(rs.length > 0) {
			commentsP8 = rs[0].get("COMMENTS");
			logger.info("IBSCheck: commentsP8 = " + commentsP8);
		} */
		var rs = exchange.getIn().getBody(java.util.List.class);
		logger.info("IBSCheck: rs = " + rs);
	
		if(rs && rs.size() > 0) {
			commentsP8 = rs.get(0).get("COMMENTS");
			var messageBytes = rs.get(0).get("MESSAGE");
			if(messageBytes) {
				messageP8 = new java.lang.String(messageBytes, "UTF-8");
			}
		}
		logger.info("IBSCheck: commentsP8 = " + commentsP8);
		logger.info("IBSCheck: messageP8 = " + messageP8);
		
		/* if(isPatternPresent(commentsP8, "11593")){
			custom13 = replacePattern(custom13, "IBS=Y", "IBS=N");
			logger.info("IBSCheck: custom13 = " + custom13);
			setHeader(map, "PLCN_custom13", custom13);
		} */
		if(isPatternPresent(messageP8, "<Cd>8000</Cd>")){
			logger.info("IBSCheck: inside 8000 if ");
			custom13 = replacePattern(custom13, "IBS=Y", "IBS=N");
			logger.info("IBSCheck: custom13 = " + custom13);
			setHeader(map, "PLCN_custom13", custom13);
		}else {
			var value;
			var result;
			var i = 0;
			
			const values = ["11593","7130","7926","7928","7513","7621","7620","7135","7136","8020","7907","7906","7903","7813","7834","7835","7814","7815","7816","7811","7812","7930","7931","7932","7933","7934","7833","7828","7872","7909","7181","7182","7183","7186","7189","7190","7187","7188","7186","7191","7192","7194","7195","5707","7199","8006","7200","7064","7066","5703","5701","5702","5770","7042","7043","5773","7041","8021","7040","7039","8019","7869","7870","7871","7193","7065","7904","8183"];
			var valuesLength = values.length;
		
			while (i < valuesLength) {
				logger.info("IBSCheck: inside while loop");
				value = values[i];
				logger.info("IBSCheck: value = " + value);
				result = isPatternPresent(commentsP8, value);
				logger.info("IBSCheck: result = " + result);
				if(result == true) {
					custom13 = replacePattern(custom13, "IBS=Y", "IBS=N");
					logger.info("IBSCheck: custom13 = " + custom13);
					setHeader(map, "PLCN_custom13", custom13);
					i = valuesLength;
				}
				i++;
			}
		}
	}
	
	if(isPatternPresent(custom13, "IBS=Y")){		
		IBSCheckConfigured = true;		
	}else {
		IBSCheckConfigured = false;
	}
	
	logger.info("IBSCheck: IBSCheckConfigured = " + IBSCheckConfigured);
	setHeader(map, "PLCN_IBSCheckConfigured", IBSCheckConfigured);	

	if(IBSCheckConfigured == false) {
		setHeader(map, "PLCN_IBSCheckExit", false);
	}else{
		setHeader(map, "PLCN_IBSCheckExit", true);
	}
	
	var bodyInIBS = getHeader(map, "OrgBody_IBS");
	logger.info("IBSCheck: bodyInIBS = " + bodyInIBS);

	if(bodyInIBS){
		logger.info("IBSCheck: setting msg body");
		inMsg.setBody(bodyInIBS);
	}
}

function checkIBSConfig(exchange) {
    var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
    var inMsg = exchange.getIn();
    var map = inMsg.getHeaders();
    //var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	logger.info("In checkIBSConfig");

	var messageBody = convertDocumentToString(Document);
	logger.info("checkIBSConfig: messageBody = " + messageBody);
	setHeader(map, "ACEDB_OrgBody",messageBody);
	
	var institutionId =  getHeader(map, "PLCN_institutionId");
	logger.info("checkIBSConfig: institutionId = " + institutionId);

	var msgFamily =  getHeader(map, "PLCN_msgFamily");
	logger.info("checkIBSConfig: msgFamily = " + msgFamily);
	
	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("checkIBSConfig: msgDirection = " + msgDirection);
	
	// var key1 = institutionId + "."+ "MESSAGE_PROCESSING.FUNCTIONALITY.IBIS" + "." + msgFamily + "_CONFIG";
 //    logger.info("checkIBSConfig: key1 = " + key1);

 //    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
 //    //value1 = "SSB"; //for testing
 //    logger.info("checkIBSConfig: value1 = " + value1);

 //    if(value1) {
 //   		logger.info("checkIBSConfig: calling IBS route for " + value1);
	// 	setHeader(map, "PLCN_IBSCheckSSB", true);
	// 	setHeader(map, "PLCNAPI_IBSCheckSSB", true);
	// }else {
 //   		logger.info("checkIBSConfig: calling IBS route for Product");
 //   		setHeader(map, "PLCN_IBSCheckPRD", true);    	
 //    }

    var msgType = getHeader(map, "PLCN_msgType");
	logger.info("checkIBSConfig: msgType = " + msgType);
	
	var creditorAccountPath;
	var debtorAccountPath;
	var accountValue;
 
	if(msgType == "pacs.008.001.08") {
		if(msgDirection == "I") {
			debtorAccountPath  = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/DbtrAcct/Id/IBAN';
			accountValue  = getValueFromPath(Document, debtorAccountPath);
			logger.info("checkIBSConfig:pacs.008.001.08 accountValue = " + accountValue);
			setHeader(map, "PLCN_fundCodeEnrich", true); 
		}else {
			creditorAccountPath  = 'Document/FIToFICstmrCdtTrf/CdtTrfTxInf/CdtrAcct/Id/IBAN';
			accountValue  = getValueFromPath(Document, creditorAccountPath);
			logger.info("checkIBSConfig:pacs.008.001.08 accountValue = " + accountValue);
			setHeader(map, "PLCN_fundCodeEnrich", true); 
		}
	}else if(msgType == "pacs.004.001.09"){
		//SSBTC-279
		if(msgDirection == "I") {
			creditorAccountPath  = 'Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN';
			accountValue  = getValueFromPath(Document, creditorAccountPath);
			logger.info("checkIBSConfig: pacs.004.001.09 accountValue = " + accountValue);
			setHeader(map, "PLCN_fundCodeEnrich", true); 
		}else {
			debtorAccountPath  = 'Document/PmtRtr/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN';
			accountValue  = getValueFromPath(Document, debtorAccountPath);
			logger.info("checkIBSConfig: pacs.004.001.09 accountValue = " + accountValue);
			setHeader(map, "PLCN_fundCodeEnrich", true); 
		}
	}else if(msgType == "pacs.003.001.08"){
		//added for IB P3
		debtorAccountPath  = 'Document/FIToFICstmrDrctDbt/DrctDbtTxInf/DbtrAcct/Id/IBAN';
		accountValue  = getValueFromPath(Document, debtorAccountPath);
		logger.info("checkIBSConfig: pacs.003.001.08 accountValue = " + accountValue);
		setHeader(map, "PLCN_fundCodeEnrich", true); 
	}else if(msgType == "pacs.007.001.09"){
		//added for IB P7
		debtorAccountPath  = 'Document/FIToFIPmtRvsl/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN';
		accountValue  = getValueFromPath(Document, debtorAccountPath);
		logger.info("checkIBSConfig: pacs.007.001.09 accountValue = " + accountValue);
		setHeader(map, "PLCN_fundCodeEnrich", true); 
	}
	// else if(msgType == "pacs.002.001.10") {
	// 	creditorAccountPath  = 'Document/FIToFIPmtStsRptSCL/TxInfAndSts/OrgnlTxRef/CdtrAcct/Id/IBAN';
	// 	creditorAccount  = getValueFromPath(Document, creditorAccountPath);
	// 	logger.info("checkIBSConfig: pacs.002.001.10 creditorAccount = " + creditorAccount);
	// }
	setHeader(map, "PLCN_AccountId",accountValue); 

	setHeader(map, "PLCN_nextWorkFlowQueueId", "APRVTXNQ");
	setHeader(map, "PLCN_nextWorkFlowStatus", "69");

	var processingStage = "APRV";
	
	setHeader(map, "PLCN_processingStage", processingStage);

	var key1 = institutionId + "."+ "INSTITUTION_DETAILS.AUTHENTICATION_LEVEL.STAGES.APPROVE" + "." + "STAGE_ACCESS_CONTROL";
    logger.info("checkIBSConfig: key1 = " + key1);

    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
    logger.info("checkIBSConfig: value1 from INST_PARAM = " + value1);

    if(msgDirection == "I") {
	    if(value1 == "FOUR") {
	    	value1 = processingStage+"="+"4";
	    }else if(value1 == "TWO") {
	    	value1 = processingStage+"="+"2";
	    }else if(value1 == "SIX") {
	    	value1 = processingStage+"="+"6";
	    }
	    setHeader(map, "PLCN_displayFlag", "Y");
	    setHeader(map, "PLCN_currentAuthLevel", value1);
  		setHeader(map, "PLCNAPI_currentAuthLevel", value1);
	}else if(msgDirection == "O"&& msgType == "pacs.003.001.08"){
		 if(value1 == "FOUR") {
	    	value1 = processingStage+"="+"4";
	    }else if(value1 == "TWO") {
	    	value1 = processingStage+"="+"2";
	    }else if(value1 == "SIX") {
	    	value1 = processingStage+"="+"6";
	    }
	    setHeader(map, "PLCN_displayFlag", "Y");
	    setHeader(map, "PLCN_currentAuthLevel", value1);
  		setHeader(map, "PLCNAPI_currentAuthLevel", value1);
	}else {
		setHeader(map, "PLCN_displayFlag", "Y");
	}

    logger.info("checkIBSConfig: current Auth Level = " + value1);
    

 //    var custom13 = replacePattern(custom13, "IBS=Y|", "IBS=D|");
	// logger.info('checkIBSConfig: custom13 = ' + custom13);
	// setHeader(map, "PLCN_custom13", custom13);
}

function setDataForIBS(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();

	logger.info("In setDataForIBS");

	var jsonbody = inMsg.getBody(java.lang.String.class);
	if(jsonbody) {
		jsonbody = JSON.parse(jsonbody);
	}
	logger.info("setDataForIBIS: jsonbody = " + jsonbody);

	var messageBody = getHeader(map, "ACEDB_OrgBody");

	inMsg.setBody(messageBody);

	var parser = new XMLParser();
	var body = inMsg.getBody(java.lang.String.class);
	var Document = parser.parseXML(body);
	logger.info("setDataForIBIS: body = " + body);	

	var institutionId =  getHeader(map, "PLCN_institutionId");
	logger.info("setDataForIBIS: institutionId = " + institutionId);

	var msgFamily =  getHeader(map, "PLCN_msgFamily");
	logger.info("setDataForIBIS: msgFamily = " + msgFamily);

	var msgType = getHeader(map, "PLCN_msgType");
	logger.info("setDataForIBIS: msgType = " + msgType);

	var msgDirection = getHeader(map, "PLCN_msgDirection");
 	logger.info("setDataForIBIS: msgDirection = " + msgDirection);

	var fundCode = jsonbody.fund_code;//"ABC123FUND01";
	logger.info("setDataForIBIS: fundCode = " + fundCode);

	if(fundCode) {
		if(msgType == "pacs.008.001.08") {
			if(msgDirection == "I") {
				Document = setValueInPath(Document, "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/DbtrAcct/Id/IBAN", fundCode);
			}else {
				Document = setValueInPath(Document, "/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/CdtrAcct/Id/IBAN", fundCode);
			}
		}else if(msgType == "pacs.004.001.09") {
			//SSBTC-279
			if(msgDirection == "I") {
				Document = setValueInPath(Document, "/Document/PmtRtr/TxInf/OrgnlTxRef/CdtrAcct/Id/IBAN", fundCode);
			}else {
				Document = setValueInPath(Document, "/Document/PmtRtr/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN", fundCode);
			}
		}else if(msgType == "pacs.003.001.08") {
			//added for IB P3
			Document = setValueInPath(Document, "/Document/FIToFICstmrDrctDbt/DrctDbtTxInf/DbtrAcct/Id/IBAN", fundCode);
		}else if(msgType == "pacs.007.001.09") {
			//added for IB P7
			Document = setValueInPath(Document, "/Document/FIToFIPmtRvsl/TxInf/OrgnlTxRef/DbtrAcct/Id/IBAN", fundCode);
		}
	}
	// else if(msgType == "pacs.002.001.10") {
	// 	Document = setValueInPath(Document, "/Document/FIToFIPmtStsRptSCL/TxInfAndSts/OrgnlTxRef/CdtrAcct/Id/IBAN", fundCode);
	// }

	var message = convertDocumentToString(Document);
	logger.info("setDataForIBIS: message = " + message);

	setHeader(map, "ACEDB_MSGBLOCK154", message);

	setHeader(map, "ACEDB_MSGBLOCK190", message);
}

