function dbOperationTranslationP4(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var messageBody = inMsg.getBody(java.lang.String.class);
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	var msgdbMap = new HashMap();
	var msgBlocks = new HashMap();
	var audit = new HashMap();
	var list = new ArrayList();
	var Msgblock1 = new HashMap();
	var Msgblock2 = new HashMap();
	var Msgblock6 = new HashMap();
	var Msgblock154 = new HashMap();
	var sourceChannelId;
	var channelIdTarget;
	var linkCode;

	logger.info("In dbOperationTranslationP4");

	var msgType = getMessageType(exchange); //getHeader(map, "PLCN_msgType");
	msgType = msgType.toLowerCase();
	logger.info("dbOperationTranslationP4: msgType = " + msgType);

	var msgFamily = getHeader(map, "PLCN_msgFamily");
	logger.info("dbOperationTranslationP4: msgFamily = " + msgFamily);

	var mode = getHeader(map, "PLCN_mode");
	logger.info("dbOperationTranslationP4: mode = " + mode);

	var srcPymtType = getHeader(map, "SRC_PaymentType");
	logger.info("dbOperationTranslationP4: srcPymtType = " + srcPymtType);

	//var sourceChannelId = getHeader(map, "PLCN_sourceChannelId");
	//logger.info("dbOperationTranslation: sourceChannelId = " + sourceChannelId);

	if(msgType == "pacs.008.001.08" || msgType == "pacs.003.001.08") {
		logger.info("dbOperationTranslationP4: msgType = " + msgType);
		msgdbMap.put("ORG_MESSAGECLASSTYPE", "");
		

    	var custom5 = getHeader(map, "PLCN_custom5Dupl");
    	logger.info('dbOperationTranslation: custom5 from PLCN_custom5Dupl = ' + custom5);

    	var custom5Tmp = getHeader(map, "PLCN_custom5");
    	logger.info('dbOperationTranslation: custom5Tmp from PLCN_custom5 = ' + custom5Tmp);
		
		var reasonCodeP8 = getHeader(map, "PLCN_reasonCodeP8");
    	logger.info('dbOperationTranslation: reasonCodeP8 = ' + reasonCodeP8);
		if(!reasonCodeP8) {
			reasonCodeP8 = readMsgdb.get("REASON_CODE");
			logger.info('dbOperationTranslation: reasonCodeP8 from db = ' + reasonCodeP8);
		}
		setHeader(map, "PLCN_reasonCodeP8", reasonCodeP8);
		msgdbMap.put("REASON_CODE", "");
		
		if(custom5) {
			custom5 = custom5 + "|ADOR" + "?";
			logger.info('dbOperationSepa: custom5 after remove pattern and concat = ' + custom5);
		}

    	if(custom5 == null || custom5 == "" || !custom5){
    		custom5 = getHeader(map, "PLCN_custom5");
    		logger.info('dbOperationTranslation: custom5 from PLCN_custom5 = ' + custom5);
    	}

    	var msgIdP4 = getHeader(map, "ACEQ_MSGDBID");
    	logger.info('dbOperationTranslation: msgIdP4 = ' + msgIdP4);

    	if(custom5 == null || custom5 == "" || !custom5) {
    		var custom5P8 = custom5 + "NEXT=" + msgIdP4 + "|OPRT" + "?";	//need to configure new value in tabledetails
    	}else{
    		var custom5P8 = "NEXT=" + msgIdP4 + "|OPRT" + "?"; //need to configure new value in tabledetails
    	}

		logger.info("dbOperationTranslation: custom5P8 = " + custom5P8);

		//if(msgFamily == "SEPAINST") {
			msgdbMap.put("CUSTOM5", custom5P8);
		//}
		
		//TBSEETHTY-10255
		msgdbMap.put("PROCESSING_STAGE", "FINL");

		var messageNo = getHeader(map, "PLCN_messageNo");
		logger.info("dbOperationTranslation: messageNo = " + messageNo);

		var institutionId = getHeader(map, "PLCN_institutionId");
		logger.info("dbOperationTranslation: institutionId = " + institutionId);

		var prevQueueId = getHeader(map, "PLCN_queueId");
		logger.info("dbOperationTranslation: prevQueueId = " + prevQueueId);

		audit.put("MESSAGENO", messageNo);
		audit.put("QUEUEID", "PROCDQ");
		//audit.put("USERNAME","ADMIN1");
		audit.put("APPLICATION","SEPAPPAY");
		audit.put("MODULENAME","ACEQWRITE");
		audit.put("ACTION","UPDATE");
		audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " read from Queue <"+ prevQueueId + ">" +" and written into Queue " +  "<" + "PROCDQ" + ">");
		audit.put("INSTITUTIONID", institutionId);

		setHeader(map, "GENAUDIT", audit);
		setHeader(map, "ACEQ_WRITE_MSGDB", msgdbMap);
		setHeader(map, "ACEQ_DB_OPERATION", "UPDATE");
	}

	if(msgType == "pacs.004.001.09") {
		logger.info("dbOperationTranslation: msgType = " + msgType);

		var msgIdP8 = getHeader(map, "PLCN_msgDbId");
		logger.info("dbOperationTranslation: msgIdP8 = " + msgIdP8);

		var institutionIdPacs4 = getHeader(map, "PLCN_institutionIdPacs4");
		logger.info("dbOperationTranslation: institutionIdPacs4 = " + institutionIdPacs4);

		var sourceChannelId =  getHeader(map, "PLCN_sourceChannelId");
		logger.info("dbOperationTranslation: sourceChannelId = " + sourceChannelId);

		var amount = getHeader(map, "PLCN_priorityAmount");
		logger.info("dbOperationTranslation: amount = " + amount);
		msgdbMap.put("PRIORITYAMOUNT", amount);

		var country = getHeader(map, "ACEDB_country");
		logger.info("dbOperationTranslation: country = " + country);

		var currency = getHeader(map, "ACEDB_currency");
		logger.info("dbOperationTranslation: currency = " + currency);
		msgdbMap.put("CURRENCY", currency);

		var priorityAmtNo = getHeader(map, "ACEDB_priorityAmtNo");
		logger.info("dbOperationTranslation: priorityAmtNo = " + priorityAmtNo);
		//msgdbMap.put("PRIORITYAMOUNTNUM", priorityAmtNo);

		var receiver = getHeader(map, "PLCN_receiver");
		logger.info("dbOperationTranslation: receiver = " + receiver);
		msgdbMap.put("RECEIVER", receiver);

		var sender = getHeader(map, "PLCN_sender");
		logger.info("dbOperationTranslation: sender = " + sender);
		msgdbMap.put("SENDER", sender);

		//var transRef = getHeader(map, "PLCN_transRefNo");
		var transrefno4 = "/Document/PmtRtr/TxInf/RtrId";
		var transRef = getValueFromPath(Document, transrefno4);
		logger.info("dbOperationTranslation: transRef = " + transRef);

		msgdbMap.put("TRANSREFNO", transRef);

		var valueDate = getHeader(map, "PLCN_valueDate");	
		logger.info("dbOperationTranslation: valueDate = " + valueDate);
		msgdbMap.put("PRIORITYDATE", valueDate);

		var reasonCdP8 = getHeader(map, "PLCN_reasonCodeP8");
		logger.info("dbOperationTranslation: reasonCdP8 = " + reasonCdP8);
		var reasonCdPath = "/Document/PmtRtr/TxInf/RtrRsnInf/Rsn/Cd";
		setValueInPath(Document, reasonCdPath, reasonCdP8);
		
		var msgDirection = getHeader(map, "PLCN_msgDirection");	
		logger.info("dbOperationTranslation: msgDirection = " + msgDirection);
		if(msgDirection == 'I') {
			msgDirection == 'O';
			linkCode = "|OFCT?";
		}else{
			msgDirection == 'I';
			linkCode = "|IFCT?";
		}

		msgdbMap.put("MESSAGEDIRECTION", "I");

		var custom5P4 = "PREV=" + msgIdP8 + linkCode;
		logger.info("dbOperationTranslation: custom5P4 = " + custom5P4);
		msgdbMap.put("CUSTOM5", custom5P4);

		/*if(msgDirection == 'I') {
			setHeader(map, "PLCN_sourceChannelId", "PEL-OB-IN");
		}else{
			setHeader(map, "PLCN_sourceChannelId", "SWF-FIN-IN");
		}*/

		var sourceChannelId = getHeader(map, "PLCN_sourceChannelId");
		//var sourceChannelIdP2 = memTblGetTableValue(map, "USER_CONFIG_MAP", sourceChannelId);
		channelIdTarget = memTblGetTableValue(map, "MQ_CHANNEL_CONF_MAP", sourceChannelId + "-ERR"); //memTblGetTableValue(map, "MQ_CHANNEL_CONF_MAP", sourceChannelIdP2);
		logger.info("dbOperationTranslation: sourceChannelId = " + sourceChannelId);
		logger.info("dbOperationTranslation: channelIdTarget = " + channelIdTarget);

		var tenantNamePath = institutionIdPacs4 + ".INSTITUTION_DETAILS.TENANT_NAME";
		logger.info("dbOperationTranslation: tenantName = " + tenantNamePath);
		tenantName = memTblGetTableValue(map, "INST_PARAM",tenantNamePath);
		logger.info("dbOperationTranslation: tenantName = " + tenantName);
		msgdbMap.put("TENANT_NAME", tenantName);

		msgdbMap.put("MSG_FAMILY", msgFamily);
		msgdbMap.put("MESSAGECLASSTYPE", "pacs.004.001.09");
		msgdbMap.put("INSTITUTIONID", institutionIdPacs4);		
		msgdbMap.put("SOURCECHANNELID", "PELICAN");
		msgdbMap.put("CHANNEL_ID_SOURCE", "PELICAN");
		msgdbMap.put("CHANNEL_ID_TARGET", channelIdTarget);
		msgdbMap.put("MSG_MODE_IN", "PELICAN");

		if(institutionIdPacs4 == "SBOSUS33") {
			msgdbMap.put("MSGSEGR", "SSB NY");
		}else {
				msgdbMap.put("MSGSEGR", "DEFAULT");
		}
		
		if(mode == "FILE") {
			setHeader(map, "PLCN_eQueueId", "SEPABLKQ");
			setHeader(map, "PLCN_eStatus", 69);
		}else {
			msgdbMap.put("CHANNEL_ID_TARGET", channelIdTarget);
			msgdbMap.put("NEXT_WORKFLOW_QUEUE_ID", "PROCDQ");
			msgdbMap.put("NEXT_WORKFLOW_STATUS", "84");
			setHeader(map, "PLCN_eQueueId", "TMPMSGQ");
			setHeader(map, "PLCN_eStatus", 69);
		}
		
		msgdbMap.put("PROCESSING_STAGE", "FINL");
		msgdbMap.put("NEXT_WORKFLOW_QUEUE_ID", "PROCDQ");
		msgdbMap.put("NEXT_WORKFLOW_STATUS", "84");
		msgdbMap.put("DISPLAY_FLAG", "Y");
		msgdbMap.put("TRANSACTIONGROUP", "ENI");
		msgdbMap.put("DERIVED_PRODUCT", "OB-SEPA-RTR-IN");
		msgdbMap.put("TRANSACTIONTYPE", "S");

		Msgblock1.put("MSGBLOCKTYPE", "1");
		Msgblock2.put("MSGBLOCKTYPE", "2");
		Msgblock154.put("MSGBLOCKTYPE", "154");
		Msgblock1.put("MESSAGE", "CAMEL_EXCHANGE_BODY");
		Msgblock2.put("MESSAGE", "CAMEL_EXCHANGE_BODY");
		Msgblock154.put("MESSAGE", "CAMEL_EXCHANGE_BODY");
		Msgblock1.put("MSGFAMILY", "XML");
		Msgblock2.put("MSGFAMILY", "XML");
		Msgblock154.put("MSGFAMILY", "XML");

		list.add(Msgblock1);
		list.add(Msgblock2);
		list.add(Msgblock154);

		var responseCdsDoc = getHeader(map, "ACEDB_responseCdsDoc");
		logger.trace("dbOperationTranslation: typeof responseCdsDoc = " + typeof responseCdsDoc);
		logger.info("dbOperationTranslation: responseCdsDoc = " + responseCdsDoc);

		if(responseCdsDoc && isPatternPresent(responseCdsDoc, "<ResponseCds>")) {
			Msgblock6.put("MSGBLOCKTYPE", "6");
			Msgblock6.put("MESSAGE", responseCdsDoc);
			Msgblock6.put("MSGFAMILY", "XML");
			list.add(Msgblock6);
			logger.info("dbOperationTranslation: Msgblock6 = " + Msgblock6);
			logger.info("dbOperationTranslation: Msgblock6 inserted");
		}		
		
		logger.info("dbOperationTranslation: list = " + list);

		var messageNo = getHeader(map, "ACEQ_MESSAGENO");
		logger.info("dbOperationTranslation: pacs.004 messageNo = " + messageNo);

		audit.put("MESSAGENO", messageNo);
		audit.put("QUEUEID", "TMPMSGQ");
		//audit.put("USERNAME","ADMIN1");
		audit.put("APPLICATION","SEPAPPAY");
		audit.put("MODULENAME","ACEQWRITE");
		audit.put("ACTION","WRITE");
		audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " read from DB and written into Queue " +  "<" + "TMPMSGQ" + ">");
		audit.put("INSTITUTIONID", institutionIdPacs4);

		setHeader(map, "GENAUDIT", audit);
		setHeader(map, "ACEQ_WRITE_MSGDB", msgdbMap);
		setHeader(map, "ACEQ_WRITE_MSGBLOCKS", list);
		setHeader(map, "ACEQ_DB_OPERATION", "INSERT");
	}

	logger.info("dbOperationTranslation completed");
}

