function setTotalAmount(exchange) {
	logger.info("In setTotalAmount rule.");

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	
	var totalAmountPath;
	var totalAmount;

	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");

	var parser = new XMLParser();
	var body = inMsg.getBody(java.lang.String.class);
	Document = parser.parseXML(body);

	var messageType = readMsgdb.get("MESSAGECLASSTYPE");
	logger.info("setTotalAmount: messageType = " + messageType);

	if(messageType == 'pacs.007.001.09') {
		totalAmountPath = '/Document/FIToFIPmtRvsl/GrpHdr/TtlRvsdIntrBkSttlmAmt';
		totalAmount = getValueFromPath(Document, totalAmountPath);
		logger.info("setTotalAmount: totalAmount = " + totalAmount);
	}else if(messageType == 'pacs.003.001.08') {
		totalAmountPath = '/Document/FIToFICstmrDrctDbt/GrpHdr/TtlIntrBkSttlmAmt';
		totalAmount = getValueFromPath(Document, totalAmountPath);
		logger.info("setTotalAmount: totalAmount = " + totalAmount);
	}

	setHeader(map, "PLCN_totalBatchAmount", totalAmount);
	exchange.setProperty("PLCN_totalBatchAmount",totalAmount);

}

function checkMirroringConfig(exchange) {
	
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var balanceMirroringConfigured;
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	
	logger.info("In checkMirroringConfig");

	var custom13 = getHeader(map, "PLCN_custom13");
	logger.info("checkMirroringConfig: custom13 = " + custom13);
	
	if(!custom13){
		var custom13 =  readMsgdb.get("CUSTOM13");	
		logger.info("checkMirroringConfig: custom13 from readMsgdb = " + custom13);		
	}
	
	var comments = getHeader(map, "PLCN_txnComments");
	logger.info("checkMirroringConfig: comments = " + comments);
	
	if(!comments){
		var comments =  readMsgdb.get("COMMENTS");	
		logger.info("checkMirroringConfig: comments from readMsgdb = " + comments);
		setHeader(map, "PLCN_txnComments", comments);
	}	

	if(isPatternPresent(custom13, "MIRRORING=Y")) {		
		balanceMirroringConfigured = true; 		
	}else {
		balanceMirroringConfigured = false; //for testing
	}

	if(balanceMirroringConfigured == false) {
		setHeader(map, "PLCN_checkMirroringConfigExit", false);
	}else{
		setHeader(map, "PLCN_checkMirroringConfigExit", true);
	}

}

function setMirroringFlag(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var Document = exchange.getIn().getBody(org.w3c.dom.Document.class);
	var dbtrCtryCode;
	var cdtrCtryCode;
	var balanceMirroringFlag;
	logger.info("In setMirroringFlag");

	var institutionId = getHeader(map, "PLCN_institutionId");
	logger.info("setMirroringFlag: institutionId = " + institutionId);
	setHeader(map, "InstitutionId", institutionId);

	var cbsKey = institutionId+"."+"MESSAGE_PROCESSING.FUNCTIONALITY.RMG.BALANCE_MIRRORING.FLAGS.CBS_UP"

	var cbsUpFlag = memTblGetTableValue(map, "INST_PARAM", cbsKey);
	logger.info("setMirroringFlag:cbsUpFlag = " + cbsUpFlag);
	logger.info("setMirroringFlag:cbsUpFlag = " + typeof cbsUpFlag);
	

	if(cbsUpFlag) {
		cbsUpFlag = cbsUpFlag.toLowerCase();
		logger.info("setMirroringFlag:cbsUpFlag = " + cbsUpFlag);
	}

	//cbsUpFlag = 'false'; //for testing
	//logger.info("setMirroringFlag:cbsUpFlag1 = " + cbsUpFlag);
	//logger.info("setMirroringFlag:cbsUpFlag1 = " + typeof cbsUpFlag);
	
	setHeader(map, "PLCN_cbsUPFlag", cbsUpFlag);

	var debtorIbanPath = '/Document/FIToFICstmrCdtTrf/CdtTrfTxInf/DbtrAcct/Id/IBAN';
	var debtorIban = getValueFromPath(Document, debtorIbanPath);
	setHeader(map, "PLCN_debtorIban", debtorIban);
	logger.info("setMirroringFlag:debtorIban = " + debtorIban);

	if(debtorIban) {
		dbtrCtryCode = debtorIban.substring(0,2);
		logger.info("setMirroringFlag:dbtrCtryCode = " + dbtrCtryCode);
	}

	var dbtrCountry = memTblGetTableValue(map, "ACCNT_CTRY_MAP", dbtrCtryCode);
	logger.info("setMirroringFlag: dbtrCountry = " + dbtrCountry);

	//dbtrCountry = 'N'; //for testing

	if(cbsUpFlag == 'true') {
		logger.info("setMirroringFlag: cbs is up");
		balanceMirroringFlag = false;
	}else if(cbsUpFlag == 'false'){
		logger.info("setMirroringFlag: cbs is down");
		if(dbtrCountry == 'Y') {
			logger.info("setMirroringFlag: country is DE");
			balanceMirroringFlag = false;
		}else {
			logger.info("setMirroringFlag: country is non DE");
			balanceMirroringFlag = true;
		}
	}else {
		logger.info("setMirroringFlag: cbs flag value is blank");
		balanceMirroringFlag = false;
	}

	setHeader(map, "PLCN_balanceMirroringFlag", balanceMirroringFlag);
	logger.info("setMirroringFlag: balanceMirroringFlag = " + balanceMirroringFlag);
	
	if(balanceMirroringFlag == false) {
		setHeader(map, "PLCN_checkMirroringConfigExit", false);
	}else {
		setHeader(map, "PLCN_checkMirroringConfigExit", true);
	}

}

function processCheckBalanceResponse(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();

	logger.info("In processCheckBalanceResponse");

	setHeader(map, "PLCN_checkMirroringConfigExit", false);

	var jsonData = exchange.getIn().getBody(java.lang.String.class); 
	logger.info("processCheckBalanceResponse: jsonData = " + jsonData);

	var mydata = JSON.parse(jsonData);
	logger.info("processCheckBalanceResponse: mydata = " + mydata);

	var accountId = mydata["account_Id"];
	logger.info("processCheckBalanceResponse: accountId = " + accountId);

	var status = mydata["status"];
	//status = "SUCCESS";
	logger.info("processCheckBalanceResponse: status = " + status);
	 
	var dateTime = mydata["date_time"];
	logger.info("processCheckBalanceResponse: dateTime = " + dateTime);

	if(status == "FAILURE") {
		var failureCategory = mydata["failure_category"];
		logger.info("processCheckBalanceResponse: failureCategory = " + failureCategory);		

		var error = mydata["error"];
		logger.info("processCheckBalanceResponse: error = " + error);
		
		var reasonCode = mydata.error["reason_code"];
		logger.info("processCheckBalanceResponse: reasonCode = " + reasonCode);
		
		var description = mydata.error["description"];
		logger.info("processCheckBalanceResponse: description = " + description);
		
		setHeader(map, "PLCN_balanceMirroringError"+reasonCode, true);

		if(reasonCode == "123" || reasonCode == "999") {

			setHeader(map, "PLCN_checkMirroringConfigExit", true);

			var processingStage = "PENT";
			setHeader(map, "PLCN_processingStage", processingStage);

			var institutionId = getHeader(map, "PLCN_institutionId");
			logger.info("processCheckBalanceResponse: institutionId = " + institutionId);

			var key1 = institutionId + "."+ "INSTITUTION_DETAILS.AUTHENTICATION_LEVEL.STAGES.BALANCE_CHECK" + "." + "STAGE_ACCESS_CONTROL";
		    logger.info("processCheckBalanceResponse: key1 = " + key1);

		    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		    logger.info("processCheckBalanceResponse: value1 from INST_PARAM = " + value1);

		    if(value1 == "FOUR") {
		    	value1 = processingStage+"="+"4";
		    }else if(value1 == "TWO") {
		    	value1 = processingStage+"="+"2";
		    }else if(value1 == "SIX") {
		    	value1 = processingStage+"="+"6";
		    }
			
		    setHeader(map, "PLCN_displayFlag", "Y");
		    setHeader(map, "PLCN_currentAuthLevel", value1);
	  		setHeader(map, "PLCNAPI_currentAuthLevel", value1);
			setHeader(map, "PLCN_queueAudit", "BALCHKPD");
		}

		if(reasonCode == "123"){
			setCommentsForTransaction("00", "7330", map);
		}else if(reasonCode == "456"){
			setCommentsForTransaction("00", "7331", map);
		}else if(reasonCode == "789"){
			setCommentsForTransaction("00", "7332", map);
			setHeader(map, "PLCN_queueAudit", "BLCRTRQ");
			setHeader(map, "PLCN_checkMirroringConfigExit", true);
		}else if(reasonCode == "999") {
			setCommentsForTransaction("00", "7333", map);
		}
		
		/* if(reasonCode == "789") {
			setHeader(map, "PLCN_queueAudit", "BLCRTRQ");
			setHeader(map, "PLCN_checkMirroringConfigExit", false);
		} *//* else if(reasonCode == "456") {
			setHeader(map, "PLCN_queueAudit", "SEPACCTQ");
		} */
		
		logger.info("processCheckBalanceResponse: PLCN_queueAudit = " + getHeader(map, "PLCN_queueAudit"));
	}
	
	if(status == "SUCCESS") {
		setHeader(map, "PLCN_balanceMirroringStatus", true);
		//setHeader(map, "PLCN_queueAudit", "SEPACCTQ");
	}

	if(status) {
		setHeader(map, "PLCN_mirroringFlag", true);
	}	

	var messageBody = getHeader(map, "ACEDB_originalBody");
	inMsg.setBody(messageBody);
}

function processCheckBalanceResponseRetry(exchange) {
	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();

	logger.info("In processCheckBalanceResponseRetry");

	setHeader(map, "PLCN_checkMirroringConfigExit", false);

	var jsonData = exchange.getIn().getBody(java.lang.String.class); 
	logger.info("processCheckBalanceResponseRetry: jsonData = " + jsonData);

	var mydata = JSON.parse(jsonData);
	logger.info("processCheckBalanceResponseRetry: mydata = " + mydata);

	var accountId = mydata["account_Id"];
	logger.info("processCheckBalanceResponseRetry: accountId = " + accountId);

	var status = mydata["status"];
	logger.info("processCheckBalanceResponseRetry: status = " + status);
	
	var dateTime = mydata["date_time"];
	logger.info("processCheckBalanceResponseRetry: dateTime = " + dateTime);
	
	//status = "FAILURE"; //for testing

	if(status == "FAILURE") {
		var failureCategory = mydata["failure_category"];
		logger.info("processCheckBalanceResponseRetry: failureCategory = " + failureCategory);		

		var error = mydata["error"];
		logger.info("processCheckBalanceResponseRetry: error = " + error);
		
		var reasonCode = mydata.error["reason_code"];
		logger.info("processCheckBalanceResponseRetry: reasonCode = " + reasonCode);
		
		var description = mydata.error["description"];
		logger.info("processCheckBalanceResponseRetry: description = " + description);
		
		//var reasonCode = "456"; //for testing
		setHeader(map, "PLCN_balanceMirroringError"+reasonCode, true);		
		
		if(reasonCode == "123" || reasonCode == "999") {

			setHeader(map, "PLCN_checkMirroringConfigExit", true);

			var processingStage = "PENT";
			setHeader(map, "PLCN_processingStage", processingStage);

			var institutionId = getHeader(map, "PLCN_institutionId");
			logger.info("processCheckBalanceResponse: institutionId = " + institutionId);
			
			if(!institutionId) {
				var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
				institutionId =  readMsgdb.get("INSTITUTIONID");
				logger.info("processCheckBalanceResponse: institutionId from readMsgdb = " + institutionId);	
			}

			var key1 = institutionId + "."+ "INSTITUTION_DETAILS.AUTHENTICATION_LEVEL.STAGES.BALANCE_CHECK" + "." + "STAGE_ACCESS_CONTROL";
		    logger.info("processCheckBalanceResponseRetry: key1 = " + key1);

		    var value1 = memTblGetTableValue(map, "INST_PARAM", key1);
		    logger.info("processCheckBalanceResponseRetry: value1 from INST_PARAM = " + value1);

		    if(value1 == "FOUR") {
		    	value1 = processingStage+"="+"4";
		    }else if(value1 == "TWO") {
		    	value1 = processingStage+"="+"2";
		    }else if(value1 == "SIX") {
		    	value1 = processingStage+"="+"6";
		    }
			
			logger.info("processCheckBalanceResponseRetry: PLCN_currentAuthLevel = " + value1);
		    setHeader(map, "PLCN_displayFlag", "Y");
		    setHeader(map, "PLCN_currentAuthLevel", value1);
	  		//setHeader(map, "PLCNAPI_currentAuthLevel", value1);
			setHeader(map, "PLCN_queueAudit", "BALCHKPD");
		}

		if(reasonCode == "123"){
			setCommentsForTransaction("00", "7330", map);
		}else if(reasonCode == "456"){
			setCommentsForTransaction("00", "7331", map);
		}else if(reasonCode == "789"){
			setCommentsForTransaction("00", "7332", map);
		}else if(reasonCode == "999") {
			setCommentsForTransaction("00", "7333", map);
		}
		
		if(reasonCode == "789") {
			setHeader(map, "PLCN_queueAudit", "BLCRTRQ");
		}else if(reasonCode == "456") {
			setHeader(map, "PLCN_queueAudit", "SEPACCTQ");
		}
		
		logger.info("processCheckBalanceResponseRetry: PLCN_queueAudit = " + getHeader(map, "PLCN_queueAudit"));
	}
	
	if(status == "SUCCESS") {
		setHeader(map, "PLCN_balanceMirroringStatus", true);
		setHeader(map, "PLCN_queueAudit", "SEPACCTQ");
		logger.info("processCheckBalanceResponseRetry: PLCN_queueAudit for SUCCESS = " + getHeader(map, "PLCN_queueAudit"));
	}

	if(status) {
		setHeader(map, "PLCN_mirroringFlag", true);
	}	

	/* var messageBody = getHeader(map, "ACEDB_originalBody"); //for testing
	inMsg.setBody(messageBody); */ 
}

function dbOperationCheckBalance(exchange) {
	logger.info("In dbOperationCheckBalance");

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	var list = new ArrayList();
	var audit = new HashMap();
	var readMsgdb = inMsg.getHeaders().get("ACEQ_READ_MSGDB");
	var msgdbMap = new HashMap();
	var readMsgdbMap = new HashMap();
	
	if(readMsgdb) {
		logger.info("dbOperationCheckBalance: values from readMsgdb");
		var messageNo = readMsgdb.get("MESSAGENO");
		logger.info("dbOperationCheckBalance: messageNo = " + messageNo);	
		
		var institutionId = readMsgdb.get("INSTITUTIONID");
		logger.info("dbOperationCheckBalance: institutionId = " + institutionId);
		
		var custom13 =  readMsgdb.get("CUSTOM13");
		logger.info("dbOperationCheckBalance: custom13 = " + custom13);
		custom13 = replacePattern(custom13, "MIRRORING=Y|", "MIRRORING=D|");	
		msgdbMap.put("CUSTOM13", custom13);
	}else {
		logger.info("dbOperationCheckBalance: values from header");
		var messageNo = getHeader(map, "PLCN_messageno");
		logger.info("dbOperationCheckBalance: messageNo = " + messageNo);
		readMsgdbMap.put("MESSAGENO", messageNo);
		
		var institutionId = getHeader(map, "PLCN_institutionId");
		logger.info("dbOperationCheckBalance: institutionId = " + institutionId);
		
		var custom13 =  getHeader(map, "PLCN_custom13");
		logger.info("dbOperationCheckBalance: custom13 = " + custom13);
		custom13 = replacePattern(custom13, "MIRRORING=Y|", "MIRRORING=D|");	
		msgdbMap.put("CUSTOM13", custom13);
		
		var msgdbId = getHeader(map, "PLCN_msgdbId");
		logger.info("dbOperationCheckBalance: msgdbId = " + msgdbId);
		readMsgdbMap.put("MSGDB_ID", msgdbId);
		
		var currqueueindate = getHeader(map, "PLCN_currQueueInDate");
		logger.info("dbOperationCheckBalance: currqueueindate = " + currqueueindate);
		readMsgdbMap.put("CURRQUEUEINDATE", currqueueindate);
		
		var currqueueintime = getHeader(map, "PLCN_currQueueInTime");
		logger.info("dbOperationCheckBalance: currqueueintime = " + currqueueintime);
		readMsgdbMap.put("CURRQUEUEINTIME", currqueueintime);
		readMsgdbMap.put("QUEUEID", "BLCRTRQ");
		setHeader(map, "ACEQ_READ_MSGDB", readMsgdbMap);
	}
	
	var queue = getHeader(map, "PLCN_queueAudit");
	logger.info("dbOperationCheckBalance: queue = " + queue);

	var authLvl = getHeader(map, "PLCN_currentAuthLevel");
	logger.info("dbOperationCheckBalance: authLvl = " + authLvl);
	
	var processingStage = getHeader(map, "PLCN_processingStage");
	logger.info("dbOperationCheckBalance: processingStage = " + processingStage);
	
	var comments = getHeader(map, "PLCN_txnComments");
	logger.info("dbOperationCheckBalance: comments = " + comments);
	
	if(authLvl) {
		msgdbMap.put("CURRENT_AUTH_LEVEL", authLvl);
	}
	
	if(processingStage) {
		msgdbMap.put("PROCESSING_STAGE", processingStage);
	}
	
	if(comments) {
		msgdbMap.put("COMMENTS", comments);
	}
	
	logger.info("dbOperationCheckBalance: msgdbMap = " + msgdbMap);
	
	audit.put("MESSAGENO", messageNo);
	audit.put("QUEUEID", getHeader(map, "PLCN_queueAudit"));
	audit.put("APPLICATION","SEPAPPAY");
	audit.put("MODULENAME","ACEQWRITE");
	audit.put("ACTION","WRITE");
	audit.put("AUDITTEXT","Pelican ID " +  "<" + messageNo + ">" + " read from 'BLCRTRQ' and written into Queue " +  "<" + getHeader(map, "PLCN_queueAudit") + ">");
	audit.put("INSTITUTIONID", institutionId);

	setHeader(map, "ACEQ_WRITE_MSGDB", msgdbMap);
	setHeader(map, "ACEQ_DB_OPERATION", "UPDATE");
	setHeader(map, "GENAUDIT", audit);
	logger.info("dbOperationCheckBalance: map = " + map);
}

function extractQueryData(exchange) {
	logger.info("In extractQueryData");

	var inMsg = exchange.getIn();
	var map = inMsg.getHeaders();
	logger.info("extractQueryData: map = " + map);	
	
	var body = exchange.getIn().getBody(java.util.List.class);
	logger.info("extractQueryData: body = " + body);

	var rowMap = body[0];

	var msgdbId = rowMap.get("MSGDB_ID");
	logger.info("extractQueryData: msgdbId = " + msgdbId);
	var messageno = rowMap.get("MESSAGENO");
	logger.info("extractQueryData: messageno = " + messageno);
	var institutionid = rowMap.get("INSTITUTIONID");
	logger.info("extractQueryData: institutionid = " + institutionid);
	var accountDr = rowMap.get("ACCOUNT_DR");
	logger.info("extractQueryData: accountDr = " + accountDr);
	var priorityamount = rowMap.get("PRIORITYAMOUNT");
	logger.info("extractQueryData: priorityamount = " + priorityamount);
	var currency = rowMap.get("CURRENCY");
	logger.info("extractQueryData: currency = " + currency);
	var custom13 = rowMap.get("CUSTOM13");
	logger.info("extractQueryData: custom13 = " + custom13);
	var currqueueindate = rowMap.get("CURRQUEUEINDATE");
	logger.info("extractQueryData: currqueueindate = " + currqueueindate);
	var currqueueintime = rowMap.get("CURRQUEUEINTIME");
	logger.info("extractQueryData: currqueueintime = " + currqueueintime);
	
	setHeader(map, "PLCN_debtorIban", accountDr);
	setHeader(map, "PLCN_priorityAmount", priorityamount);
	setHeader(map, "PLCN_currency", currency);
	
	setHeader(map, "PLCN_messageno", messageno);
	setHeader(map, "PLCN_institutionId", institutionid);
	setHeader(map, "InstitutionId", institutionid);
	setHeader(map, "PLCN_custom13", custom13);
	setHeader(map, "PLCN_msgdbId", msgdbId);
	setHeader(map, "PLCN_currQueueInDate", currqueueindate);
	setHeader(map, "PLCN_currQueueInTime", currqueueintime);	
}

function removeLeadingZeros(str) {
    return str.replace(/^0+/, '') || '0';
}